// Urban Footprint — static front-end. Consumes only precomputed files in ./data
// (generated by `python -m urbanfp export`). No build step.

import { t, label, getLang, setLang, locale, checkMessage, applyStatic, MAP_LOCALE } from './i18n.js';

const DATA = 'data';
// Map tiles of the published site live in a separate GitHub Pages repository (`tiles` of each city in
// index.json), so the app's deploys stay small; a local preview reads them from web/data like everything else.
const LOCAL = ['localhost', '127.0.0.1', '[::1]', ''].includes(location.hostname);
const tileBase = (city) => (!LOCAL && city?.tiles ? new URL(`${city.id}/`, city.tiles).href : null);
const VT_FADE = 0.5; // zoom range over which overview rasters cross-fade into vector tiles

const state = {
  index: null,
  stats: {},              // city id -> stats.json
  city: null,             // main city (map screen)
  city2: null,            // second city for the split-screen comparison (null = single map)
  view: 'map',
  unit: 'pct',            // pct | km2 | pctcat
  hidden: new Set(),      // hidden categories
  hiddenSub: new Set(),   // hidden "cat/sub"
  expanded: new Set(['buildings']),
  breakdown: 'categories',
  focus: null,            // focused category / sub-category id on the compare screen
  compareCities: null,    // selected city ids for comparison (null = all)
  opacity: 0.85,
  subPctOfCat: true,      // map sidebar: sub-category % relative to its category (true) or to the city (false)
  territory: 'city',      // territory mode: city | hromada | greater (docs/SUBURBS.md); compare screen + map pane 0
  territory2: 'city',     // territory mode of map pane 1 (split screen), so a city can be compared with itself
  aboutPage: 'overview',   // sub-page of the Method & data view
  demoYear: null,         // population (demography) reference year; null = latest available
  popMetric: 'pop',       // compare screen, population breakdown: pop | density
  budgetYear: null,       // hromada budgets: year shown (budgets.json years)
  budgetMetric: 'pc',     // compare screen, budget breakdowns: pc (per resident) | total
  financeBreakdown: 'budgetInc', // Budgets & population screen: population | budgetInc | budgetExp
  budgetFocus: null,      // Budgets & population screen: the one budget item compared (null = all)
  budgetUnit: 'total',    // map sidebar budget block: total | pc (per resident)
  budgetOpen: new Set(),  // map sidebar budget block: expanded sides (inc, exp)
  popThreshold: 30,       // population page: join settlements within this drive time (min); 0 = city only
  popSelected: null,      // population page: highlighted centre
  modelThreshold: 60,     // region modelling: drive time of the region core (min)
  regionCentres: null,    // region modelling: chosen centre ids (null = index.default_region_centres)
  modelSelected: null,    // region modelling: highlighted region
};
const TERRITORIES = ['city', 'hromada', 'greater'];

/**
 * Map panes. Pane 0 always exists; pane 1 is created when a second city is selected.
 * pane = { idx, map, cityId, layers: [], sources: [], popup, controls: [], ready: Promise }
 */
const panes = [];
let syncing = false;

// ------------------------------------------------------------------ utils
const $ = (s) => document.querySelector(s);
const el = (tag, attrs = {}, ...children) => {
  const e = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === 'class') e.className = v;
    else if (k === 'style') e.style.cssText = v;
    else if (k.startsWith('on')) e.addEventListener(k.slice(2), v);
    else if (v !== undefined && v !== null && v !== false) e.setAttribute(k, v);
  }
  for (const c of children.flat()) if (c !== null && c !== undefined) e.append(c.nodeType ? c : document.createTextNode(c));
  return e;
};
const km2 = (m2) => m2 / 1e6;
const num = (v, d) => Number(v).toLocaleString(locale(), { minimumFractionDigits: d, maximumFractionDigits: d });
const fmtKm2 = (m2) => {
  const v = km2(m2);
  return `${num(v, v >= 100 ? 0 : v >= 10 ? 1 : 2)} ${t('units.km2')}`;
};
const fmtPct = (p) => num(p, p >= 1 ? 1 : 2) + '%';
const fmtInt = (n) => Math.round(n).toLocaleString(locale());
const fmtArea = (m2) => (m2 >= 1e5 ? fmtKm2(m2) : `${fmtInt(m2)} ${t('units.m2')}`);
const isLight = (hex) => {
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));
  return 0.299 * r + 0.587 * g + 0.114 * b > 170;
};
/** City display name in the current language (Ukrainian name from OSM when in UA). */
const cityName = (c) => (getLang() === 'uk' ? c.name_local || c.name : c.name);
const cityOtherName = (c) => (getLang() === 'uk' ? c.name : c.name_local);
const cityById = (id) => state.index.cities.find((c) => c.id === id);

/** City groups from index.json, in display order (e.g. "Міста-мільйонники", "Інші міста"). */
const cityGroups = () => state.index.city_groups || [{ id: '', label: '', label_uk: '' }];

/** Sort cities by group order, then alphabetically by Ukrainian name (in both UI languages). */
function sortCities(cities) {
  const order = new Map(cityGroups().map((g, i) => [g.id, i]));
  const gi = (c) => order.get(c.group) ?? order.size;
  return [...cities].sort((a, b) => gi(a) - gi(b) || (a.name_local || a.name).localeCompare(b.name_local || b.name, 'uk'));
}

/** [{group, cities}] for non-empty groups (cities in the given, already sorted, order). */
function citiesByGroup(cities = state.index.cities) {
  const groups = cityGroups();
  const known = new Set(groups.map((g) => g.id));
  const last = groups[groups.length - 1];
  return groups
    .map((g) => ({ group: g, cities: cities.filter((c) => (c.group || '') === g.id || (g === last && !known.has(c.group || ''))) }))
    .filter((x) => x.cities.length);
}

async function getJSON(path) {
  const r = await fetch(path);
  if (!r.ok) throw new Error(`${path}: ${r.status}`);
  return r.json();
}
/*
 * stats.json holds City-mode figures at the top level and, for rebuilt cities, every territory mode under
 * `modes`. `state.stats[id]` returns a *view* for the selected territory mode with the same shape as the
 * top level (area, categories, buildings, validation...), plus:
 *   _mode    mode actually shown ('city' when the selected mode is unavailable for this city)
 *   _status  ok | same_as_city | no_hromada | occupied | not_computed
 *   _units   territory units (A = city, B/C/D = extensions) shown on the map
 */
const rawStats = {};
const viewCache = new Map();
function statsView(id, want = state.territory) {
  const raw = rawStats[id];
  const key = `${id}|${want}`;
  if (viewCache.has(key)) return viewCache.get(key);
  const md = raw.modes?.[want];
  const status = want === 'city' ? 'ok' : md ? md.status : 'not_computed';
  const usable = want === 'city' || (md && status !== 'not_computed');
  const src = usable ? (md || raw.modes?.city || raw) : (raw.modes?.city || raw);
  const view = {
    ...raw,
    area: src.area, categories: src.categories, buildings: src.buildings,
    estimated_line_footprints: src.estimated_line_footprints, network_length_km: src.network_length_km,
    validation: src.validation || raw.validation,
    _mode: usable ? want : 'city', _want: want, _status: status, _units: src.units || ['A'],
  };
  viewCache.set(key, view);
  return view;
}
state.stats = new Proxy({}, { get: (_, id) => (typeof id === 'string' && rawStats[id] ? statsView(id) : undefined) });
async function loadStats(id) {
  if (!rawStats[id]) rawStats[id] = await getJSON(`${DATA}/${id}/stats.json`);
  return state.stats[id];
}
/** Territory mode of map pane `i` (pane 1 has its own setting). */
const paneMode = (i) => (i === 1 ? state.territory2 : state.territory);
/** Stats view of the city shown in map pane `i`, for that pane's territory mode (stats must be loaded). */
const paneStats = (i) => {
  const id = i === 1 ? state.city2 : state.city;
  return id && rawStats[id] ? statsView(id, paneMode(i)) : undefined;
};
/** Names for the cities in `list` (map panes); in split screen, the territory is added when it tells them apart. */
function paneNames(list) {
  const names = list.map((x) => cityName(x.city));
  if (list.length < 2) return names;
  const showMode = list[0].city.id === list[1].city.id || list[0]._mode !== list[1]._mode;
  return showMode ? list.map((x, i) => `${names[i]} · ${t(`terr.${x._mode}`).toLowerCase()}`) : names;
}

/** Note explaining why a city shows a different territory than the selected mode (or null). */
function territoryNote(s) {
  if (s._status === 'ok' || s._want === 'city') return null;
  return t(`terr.note.${s._status}`, { mode: t(`terr.${s._want}`) });
}
// ------------------------------------------------------------------ demography
/*
 * data/demography.json (python -m urbanfp demography): population per city, year and territory mode from
 * Derzhstat (de facto population on 1 January) or a census (sources[year].kind). Optional: the app works without it.
 */
let demography = null;
async function loadDemography() {
  if (demography !== null) return demography;
  try { demography = await getJSON(`${DATA}/demography.json`); } catch { demography = { years: [], cities: {} }; }
  const years = demography.years || [];
  if (!years.includes(state.demoYear)) state.demoYear = years.length ? years[years.length - 1] : null;
  return demography;
}
const demoYears = () => demography?.years || [];
const isCensus = (y = state.demoYear) => demography?.sources?.[y]?.kind === 'census';
/** "on 1 January 2022" / "2001 census". */
const yearLabel = (y) => t(isCensus(y) ? 'demo.census' : 'demo.asOf', { year: y });
/** Source line of the selected year. */
const demoSource = () => t(isCensus() ? 'demo.sourceCensus' : 'demo.source', { year: state.demoYear });

/** Population of the territory shown by stats view `s` in the selected year, or null (no data). */
function popOf(s, year = state.demoYear) {
  const d = demography?.cities?.[s.city.id]?.[year];
  if (!d?.available) return null;
  const m = d.modes[s._mode] || d.modes.city;
  const area = s.area.boundary_km2;
  return {
    pop: m.population, cityPop: d.modes.city.population, density: m.population / Math.max(area, 1e-9),
    settlements: m.settlements || [], unmatched: m.unmatched || [],
  };
}
/** Population of a Greater City settlement (by OSM id) in the selected year, or undefined. */
function settlementPop(cityId, osm) {
  const g = demography?.cities?.[cityId]?.[state.demoYear]?.modes?.greater;
  return g?.settlements?.find((x) => x.osm === osm)?.population;
}
/** Year label, or a year switch when several years are available. */
function demoYearControl() {
  const years = demoYears();
  if (years.length < 2) return el('span', { class: 'small' }, yearLabel(state.demoYear));
  const sel = el('select', { class: 'year-select', 'aria-label': t('demo.year') },
    years.map((y) => el('option', { value: y }, yearLabel(y))));
  sel.value = state.demoYear;
  sel.addEventListener('change', () => setDemoYear(+sel.value));
  return sel;
}
function setDemoYear(year) {
  if (!demoYears().includes(year) || year === state.demoYear) return;
  state.demoYear = year;
  try { localStorage.setItem('demoYear', String(year)); } catch { /* storage unavailable */ }
  writeHash();
  renderAll();
}
/** "rest" label for the population outside the city: rest of hromada / suburbs. */
const restLabel = (mode) => t(mode === 'greater' ? 'demo.restGreater' : 'demo.restHromada');
/** Note on Derzhstat estimates for territories occupied before the reference year. */
function demoEstimateNote(c) {
  return c.occupied_since && c.occupied_since < state.demoYear ? t('demo.estimate', { year: c.occupied_since }) : null;
}

const catDef = (id) => state.index.categories.find((c) => c.id === id);
const subDef = (cat, sub) => catDef(cat)?.subcategories.find((s) => s.id === sub);

// ------------------------------------------------------------------ URL state
function readHash() {
  const p = new URLSearchParams(location.hash.slice(1));
  return {
    city: p.get('city'), city2: p.get('city2'), view: p.get('view'), territory: p.get('t'), territory2: p.get('t2'),
    year: p.get('y') ? +p.get('y') : null,
    budgetYear: p.get('by') ? +p.get('by') : null,
    financeBreakdown: p.get('show'),
    budgetFocus: p.get('item'),
    threshold: p.get('th') != null ? +p.get('th') : null,
    aboutPage: p.get('p'),
    regionCentres: p.get('rc') != null ? p.get('rc').split(',').filter(Boolean) : null,
    cities: p.get('cities') ? p.get('cities').split(',') : null,
  };
}
function writeHash() {
  const p = new URLSearchParams({ city: state.city, view: state.view });
  if (state.city2) p.set('city2', state.city2);
  if (state.territory !== 'city') p.set('t', state.territory);
  if (state.city2) p.set('t2', state.territory2);
  const years = demoYears();
  if (state.demoYear && years.length && state.demoYear !== years[years.length - 1]) p.set('y', state.demoYear);
  if ((state.view === 'compare' || state.view === 'finance') && state.compareCities) p.set('cities', compareCityIds().join(','));
  if (state.view === 'finance') {
    p.set('show', state.financeBreakdown);
    if (state.budgetFocus) p.set('item', state.budgetFocus);
  }
  if (['map', 'compare', 'finance'].includes(state.view) && budgets?.years?.length && state.budgetYear !== budgets.years[0]) {
    p.set('by', state.budgetYear);
  }
  if (state.view === 'population') p.set('th', state.popThreshold);
  if (state.view === 'modeling') {
    p.set('th', state.modelThreshold);
    if (state.regionCentres) {
      const all = agg && agg.centres.every((c) => c.settlement == null || state.regionCentres.includes(c.id));
      p.set('rc', all ? 'all' : state.regionCentres.join(','));  // every city: short link
    }
  }
  if (state.view === 'about' && state.aboutPage && state.aboutPage !== ABOUT_PAGES[0]) p.set('p', state.aboutPage);
  history.replaceState(null, '', '#' + p.toString());
}

// ------------------------------------------------------------------ tooltip
const tip = $('#tooltip');
function showTip(ev, html) {
  tip.innerHTML = html;
  tip.hidden = false;
  const x = Math.min(ev.clientX + 14, window.innerWidth - tip.offsetWidth - 8);
  const y = Math.min(ev.clientY + 14, window.innerHeight - tip.offsetHeight - 8);
  tip.style.left = x + 'px';
  tip.style.top = y + 'px';
}
const hideTip = () => (tip.hidden = true);

// ------------------------------------------------------------------ unit toggles
function renderUnitToggle(container, options) {
  container.innerHTML = '';
  for (const [id, text] of options) {
    container.append(el('button', {
      class: state.unit === id ? 'active' : '',
      onclick: () => { state.unit = id; renderAll(); },
    }, text));
  }
}

// ------------------------------------------------------------------ map panes
const BASE_STYLE = () => ({
  version: 8,
  sources: {
    osm: {
      type: 'raster', tileSize: 256, maxzoom: 19,
      tiles: ['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],
      attribution: '© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
    },
  },
  layers: [
    { id: 'bg', type: 'background', paint: { 'background-color': '#f3f3f0' } },
    {
      id: 'osm', type: 'raster', source: 'osm',
      layout: { visibility: $('#basemapToggle').checked ? 'visible' : 'none' },
      paint: { 'raster-opacity': 0.45, 'raster-saturation': -0.9 },
    },
  ],
});

function createPane(idx, containerId) {
  const map = new maplibregl.Map({
    container: containerId,
    style: BASE_STYLE(),
    center: [30.5, 50.45],
    zoom: 10,
    attributionControl: { compact: true },
    locale: { ...MAP_LOCALE[getLang()] },
    // phones report devicePixelRatio 3; rendering at 2 looks the same and needs ~half the GPU memory
    pixelRatio: Math.min(window.devicePixelRatio || 1, 2),
    maxTileCacheSize: 16, // per source (one raster source per category): bounds tile memory on phones
    dragRotate: false,       // keep both panes north-up so shapes stay comparable
    pitchWithRotate: false,
  });
  map.touchZoomRotate.disableRotation();
  const pane = { idx, map, cityId: null, layers: [], sources: [], popup: null, controls: [] };
  // resolves once the base style is loaded (isStyleLoaded() can be false later while tiles load)
  pane.ready = new Promise((res) => map.once('load', res));
  panes[idx] = pane;
  addMapControls(pane);
  map.on('click', (e) => onMapClick(pane, e));
  map.on('mousemove', (e) => { map.getCanvas().style.cursor = queryFeature(pane, e.point) ? 'pointer' : ''; });
  map.on('move', () => syncScale(pane));
  if (idx === 0) map.on('zoom', updateZoomHint);
  return pane;
}

/** (Re)create navigation + scale controls so their tooltips/units follow the current language. */
function addMapControls(pane) {
  const { map } = pane;
  for (const c of pane.controls) map.removeControl(c);
  if (map._locale) Object.assign(map._locale, MAP_LOCALE[getLang()]); // controls read it when created
  pane.controls = [new maplibregl.NavigationControl({ showCompass: false }), new maplibregl.ScaleControl({ unit: 'metric' })];
  map.addControl(pane.controls[0], 'top-right');
  map.addControl(pane.controls[1], 'bottom-left');
}

const activePanes = () => panes.filter((p) => p && p.map);
const isDual = () => !!state.city2;

function updateZoomHint() {
  const s = state.stats[state.city];
  const minz = s?.map?.vector_tiles?.minzoom ?? 14;
  $('#zoomHint').style.opacity = panes[0].map.getZoom() < minz ? 1 : 0;
}

function clearCityLayers(pane) {
  const { map } = pane;
  for (const id of pane.layers) if (map.getLayer(id)) map.removeLayer(id);
  for (const id of pane.sources) if (map.getSource(id)) map.removeSource(id);
  pane.layers = [];
  pane.sources = [];
}

function subColorExpr(cat) {
  const c = catDef(cat);
  const expr = ['match', ['get', 's']];
  for (const s of c.subcategories) expr.push(s.id, s.color);
  expr.push(c.color);
  return expr;
}

function applyOpacity() {
  for (const pane of activePanes()) {
    if (!pane.cityId) continue;
    const { map } = pane;
    const vt = rawStats[pane.cityId].map.vector_tiles;
    for (const c of state.index.categories) {
      const v = `vt-${c.id}`;
      for (const r of pane.layers.filter((id) => id.startsWith(`ov-${c.id}-`))) {
        map.setPaintProperty(r, 'raster-opacity', ['interpolate', ['linear'], ['zoom'],
          vt.minzoom, state.opacity, vt.minzoom + VT_FADE, 0]);
      }
      if (map.getLayer(v)) {
        map.setPaintProperty(v, 'fill-opacity', ['interpolate', ['linear'], ['zoom'],
          vt.minzoom, 0, vt.minzoom + VT_FADE, state.opacity]);
      }
    }
  }
}

function vtFilter(cat, pane) {
  const hiddenSubs = [...state.hiddenSub].filter((k) => k.startsWith(cat + '/')).map((k) => k.split('/')[1]);
  const f = ['all', ['==', ['get', 'c'], cat]];
  // everything outside the selected territory is hidden (tiles of rebuilt cities carry the unit `u`)
  if (pane?.unitFilter) f.push(['in', ['get', 'u'], ['literal', pane.units]]);
  if (hiddenSubs.length) f.push(['!', ['in', ['get', 's'], ['literal', hiddenSubs]]]);
  return f;
}

function applyVisibility() {
  for (const pane of activePanes()) {
    const { map } = pane;
    for (const c of state.index.categories) {
      const vis = state.hidden.has(c.id) ? 'none' : 'visible';
      for (const id of [...pane.layers.filter((x) => x.startsWith(`ov-${c.id}-`)), `vt-${c.id}`]) {
        if (map.getLayer(id)) map.setLayoutProperty(id, 'visibility', vis);
      }
      if (map.getLayer(`vt-${c.id}`)) map.setFilter(`vt-${c.id}`, vtFilter(c.id, pane));
    }
  }
}

/** The world minus the territory of `mode` (all features if null): a polygon to grey out the outside. */
function outsideMask(fc, mode) {
  const polys = [];
  for (const f of fc.features) {
    if (mode && f.properties.mode !== mode) continue;
    const g = f.geometry;
    if (g.type === 'Polygon') polys.push(g.coordinates);
    else if (g.type === 'MultiPolygon') polys.push(...g.coordinates);
  }
  const world = [[-180, -85], [180, -85], [180, 85], [-180, 85], [-180, -85]];
  const coords = [[world, ...polys.map((p) => p[0])]]; // territory outer rings are holes in the world
  for (const p of polys) for (const hole of p.slice(1)) coords.push([hole]); // enclaves stay grey
  return { type: 'Feature', properties: {}, geometry: { type: 'MultiPolygon', coordinates: coords } };
}

/** Load a city's layers into a pane (does not move the camera). */
async function loadCityIntoPane(pane, cityId) {
  await loadStats(cityId);
  const s = statsView(cityId, paneMode(pane.idx));
  await pane.ready;
  if (!pane.map) return; // pane was closed meanwhile
  const { map } = pane;
  const unitKey = s._units.join(',');
  if (pane.cityId === cityId && pane.unitKey === unitKey && pane.layers.length) return;
  // the latest call wins: an earlier load of the same city still awaiting data stops (else both add the layers)
  const token = pane.loadToken = (pane.loadToken || 0) + 1;
  const base = new URL(`${DATA}/${cityId}/`, location.href).href;
  const tiles = tileBase(cityById(cityId)) || base;  // features.pmtiles, overview.bin
  clearCityLayers(pane);
  if (pane.popup) pane.popup.remove();
  pane.cityId = cityId;
  pane.unitKey = unitKey;
  pane.units = s._units;
  pane.mode = s._mode;

  const vt = s.map.vector_tiles;
  const add = (id, spec) => { map.addSource(id, spec); pane.sources.push(id); };
  const layer = (spec) => { map.addLayer(spec); pane.layers.push(spec.id); };

  // outline of the selected territory (older exports: the city boundary). Land outside it is greyed out, so
  // unmapped land inside the territory reads differently from land that is not part of it
  const terrUrl = `${base}${s.map.territories || 'boundary.geojson'}`;
  add('boundary', { type: 'geojson', data: terrUrl });
  const modeFilter = s.map.territories ? { filter: ['==', ['get', 'mode'], s._mode] } : {};
  const terr = await getJSON(terrUrl);
  if (pane.loadToken !== token || pane.cityId !== cityId || pane.unitKey !== unitKey) return; // superseded while loading
  add('outside', { type: 'geojson', data: outsideMask(terr, s.map.territories ? s._mode : null) });
  layer({
    id: 'outside-mask', type: 'fill', source: 'outside',
    paint: { 'fill-color': '#3c3c3c', 'fill-opacity': 0.28, 'fill-antialias': false },
  });

  // overview rasters (low zoom): one tiled PMTiles pyramid per unit and category, so only visible tiles of
  // the selected territory are loaded. Older exports have one pyramid per category (city only).
  const ov = s.map.overview;
  const perUnit = Object.values(ov.files).some((v) => typeof v === 'object');
  pane.unitFilter = perUnit;
  const ovFiles = perUnit ? s._units.map((u) => [u, ov.files[u] || {}]) : [['A', ov.files]];
  // bundled export: every pyramid is an [offset, length] window of one file per city (overview.bin)
  const ovUrl = (file) => (Array.isArray(file) ? `pmtiles://${bundleSlice(tiles + ov.bundle, file)}` : `pmtiles://${base}${file}`);
  for (const c of state.index.categories) {
    for (const [u, files] of ovFiles) {
      const file = files[c.id];
      if (!file) continue;
      const id = `ov-${c.id}-${u}`;
      add(id, { type: 'raster', url: ovUrl(file), tileSize: ov.tile_size || 512 });
      layer({
        id, type: 'raster', source: id, maxzoom: vt.minzoom + VT_FADE,
        paint: { 'raster-fade-duration': 0, 'raster-resampling': 'linear' },
      });
    }
  }
  // vector tiles (high zoom) — each feature piece is exclusive, exactly what the statistics count
  add('vt', { type: 'vector', url: `pmtiles://${tiles}${vt.file}` });
  for (const c of state.index.categories) {
    layer({
      id: `vt-${c.id}`, type: 'fill', source: 'vt', 'source-layer': vt.layer, minzoom: vt.minzoom,
      filter: vtFilter(c.id, pane),
      paint: { 'fill-color': subColorExpr(c.id), 'fill-antialias': false },
    });
  }
  layer({
    id: 'vt-selected', type: 'line', source: 'vt', 'source-layer': vt.layer, minzoom: vt.minzoom,
    filter: ['==', ['get', 'id'], '__none__'],
    paint: { 'line-color': '#000', 'line-width': 2.5 },
  });
  // Hromada / Greater City: faint hairline around the whole territory (the map is empty outside it anyway),
  // so dozens of settlement outlines do not clutter the map; the city boundary stays the main reference
  const vis = $('#boundaryToggle').checked ? 'visible' : 'none';
  if (s.map.territories && s._mode !== 'city') {
    layer({
      id: 'territory-line', type: 'line', source: 'boundary',
      ...modeFilter,
      layout: { visibility: vis },
      paint: { 'line-color': '#444', 'line-opacity': 0.35, 'line-width': ['interpolate', ['linear'], ['zoom'], 9, 0.6, 15, 1.5] },
    });
  }
  layer({
    id: 'boundary-line', type: 'line', source: 'boundary',
    ...(s.map.territories ? { filter: ['==', ['get', 'mode'], 'city'] } : {}),
    layout: { visibility: vis },
    paint: { 'line-color': '#222', 'line-opacity': 0.75, 'line-width': ['interpolate', ['linear'], ['zoom'], 9, 1.2, 15, 3] },
  });
  applyOpacity();
  applyVisibility();
}

// ---- synchronised scale between panes (panning stays independent)
const cosd = (deg) => Math.cos((deg * Math.PI) / 180);

/** Zoom at which `lat` has the same metres-per-pixel as `zoom` at `refLat` (Web Mercator). */
const equalScaleZoom = (zoom, refLat, lat) => zoom + Math.log2(cosd(lat) / cosd(refLat));

/**
 * Give the other pane the same metres-per-pixel as `src`, keeping its own centre. Runs on every move
 * (not only zoom), because panning north/south also changes the Mercator scale at a fixed zoom.
 */
function syncScale(src) {
  if (syncing || !isDual()) return;
  const dst = panes[1 - src.idx];
  if (!dst?.map) return;
  const zoom = equalScaleZoom(src.map.getZoom(), src.map.getCenter().lat, dst.map.getCenter().lat);
  if (Math.abs(zoom - dst.map.getZoom()) < 1e-6) return;
  syncing = true;
  dst.map.jumpTo({ zoom });
  syncing = false;
}

/** Fit each pane to its city, using one common ground scale so sizes are directly comparable. */
function fitPanes() {
  const list = activePanes().filter((p) => p.cityId);
  if (!list.length) return;
  const cams = list.map((p) => {
    const sv = statsView(p.cityId, paneMode(p.idx));
    const b = sv.map.mode_bounds?.[sv._mode] || sv.map.bounds;
    const cam = p.map.cameraForBounds([[b[0], b[1]], [b[2], b[3]]], { padding: isDual() ? 40 : 30 });
    if (!cam) return null; // the pane is too small for the padding (e.g. while it is being laid out)
    const center = maplibregl.LngLat.convert(cam.center);
    return { p, center, res: cosd(center.lat) / 2 ** cam.zoom }; // ∝ metres per pixel
  }).filter(Boolean);
  if (!cams.length) return;
  const res = Math.max(...cams.map((c) => c.res)); // the city that needs most room sets the scale
  syncing = true;
  for (const { p, center } of cams) {
    p.map.jumpTo({ center, zoom: Math.log2(cosd(center.lat) / res) });
  }
  syncing = false;
  updateZoomHint();
}

function vtLayerIds(pane) {
  return state.index.categories.map((c) => `vt-${c.id}`).filter((id) => pane.map.getLayer(id));
}
function queryFeature(pane, point) {
  if (!pane.cityId) return null;
  const fs = pane.map.queryRenderedFeatures(point, { layers: vtLayerIds(pane) });
  return fs[0] || null;
}

function osmLink(id) {
  if (!id || id[0] === 'u') return null;
  const type = id[0] === 'w' ? 'way' : id[0] === 'r' ? 'relation' : 'node';
  return `https://www.openstreetmap.org/${type}/${id.slice(1)}`;
}

function onMapClick(pane, e) {
  const { map } = pane;
  const f = queryFeature(pane, e.point);
  if (pane.popup) pane.popup.remove();
  if (!f) {
    if (map.getLayer('vt-selected')) map.setFilter('vt-selected', ['==', ['get', 'id'], '__none__']);
    return;
  }
  const p = f.properties;
  const c = catDef(p.c), s = subDef(p.c, p.s);
  const link = osmLink(p.id);
  const rows = [
    [t('popup.area'), fmtArea(p.a)],
    p.t ? [t('popup.tag'), p.t] : null,
    p.w ? [t('popup.width'), t('popup.widthVal', { w: num(p.w, 1) })] : null,
  ].filter(Boolean);
  const html = el('div', { class: 'popup' },
    el('h4', {}, p.n || label(s) || p.s),
    el('div', { class: 'small' }, `${label(c)} › ${label(s) || p.s}`),
    el('div', { class: 'kv' }, rows.flatMap(([k, v]) => [el('span', {}, k), el('span', { class: 'v' }, v)])),
    link ? el('div', { style: 'margin-top:6px' }, el('a', { href: link, target: '_blank', rel: 'noopener' }, t('popup.osm', { id: p.id })))
      : el('div', { class: 'small', style: 'margin-top:6px' }, t('popup.noData')),
    el('div', { class: 'small', style: 'margin-top:4px' }, t('popup.note')),
  );
  pane.popup = new maplibregl.Popup({ closeButton: true, maxWidth: '320px' }).setLngLat(e.lngLat).setDOMContent(html).addTo(map);
  map.setFilter('vt-selected', ['==', ['get', 'id'], p.id]);
  pane.popup.on('close', () => {
    if (pane.map && map.getLayer('vt-selected')) map.setFilter('vt-selected', ['==', ['get', 'id'], '__none__']);
  });
}

function renderPaneLabels() {
  const dual = isDual();
  const list = [paneStats(0), paneStats(1)];
  const names = dual && list[1] ? paneNames(list) : [];
  list.forEach((s, i) => {
    const lab = $(`#paneLabel${i}`);
    lab.hidden = !dual || !s;
    if (lab.hidden) return;
    lab.innerHTML = '';
    lab.append(names[i], el('span', { class: 'small' }, ` · ${num(s.area.boundary_km2, 0)} ${t('units.km2')}`));
  });
}

/** Switch between single and split-screen layout and (re)load cities into panes. */
async function updateMaps({ fit = true } = {}) {
  const dual = isDual();
  document.querySelector('#view-map').classList.toggle('dual', dual);
  $('#pane1').hidden = !dual;
  if (dual && !panes[1]) {
    createPane(1, 'map2');
  } else if (!dual && panes[1]) {
    const p = panes[1];
    panes[1] = null;
    if (p.popup) p.popup.remove(); // close while the map still exists
    p.map.remove();
    p.map = null;
  }
  for (const p of activePanes()) p.map.resize();
  await Promise.all([
    loadCityIntoPane(panes[0], state.city),
    dual ? loadCityIntoPane(panes[1], state.city2) : null,
  ]);
  renderPaneLabels();
  if (fit) fitPanes();
}

// ------------------------------------------------------------------ sidebar
function valueText(areaM2, pct) {
  return state.unit === 'km2' ? fmtKm2(areaM2) : fmtPct(pct);
}

function cityHeader(s, osmDate) {
  const city = s.city;
  return [
    el('h1', { class: 'city-title' }, `${cityName(city)} `, el('span', { class: 'small' }, cityOtherName(city))),
    el('div', { class: 'city-meta' },
      t(s._mode === 'city' ? 'city.meta' : 'city.metaTerr', { area: num(s.area.boundary_km2, 1), mode: t(`terr.${s._mode}`).toLowerCase() }),
      el('a', { href: `https://www.openstreetmap.org/relation/${city.osm_relation}`, target: '_blank', rel: 'noopener' }, city.osm_relation),
      el('br'), t('city.osmDate', { date: osmDate })),
  ];
}
const osmDateText = (s) => (s.osm_timestamp
  ? new Date(s.osm_timestamp).toLocaleDateString(locale(), { year: 'numeric', month: 'long', day: 'numeric' }) : '—');

function renderSidebar() {
  const s = paneStats(0);
  if (!s) return;
  const s2 = isDual() ? paneStats(1) : null;
  if (isDual() && !s2) return;
  const list = s2 ? [s, s2] : [s];
  const names = paneNames(list);
  // narrow column headers: the territory alone when both panes show the same city
  const colNames = s2 && s.city.id === s2.city.id ? list.map((x) => t(`terr.${x._mode}`)) : names;

  // ---- header
  const head = $('#cityHeader');
  head.innerHTML = '';
  if (!s2) {
    head.append(...cityHeader(s, osmDateText(s)));
  } else {
    head.append(el('div', { class: 'dual-head' }, list.map((x, i) =>
      el('div', { class: 'dual-city' },
        el('span', { class: `city-key k${i}` }),
        el('div', {},
          el('div', { class: 'name' }, names[i]),
          el('div', { class: 'small' }, `${num(x.area.boundary_km2, 1)} ${t('units.km2')} · `,
            el('a', { href: `https://www.openstreetmap.org/relation/${x.city.osm_relation}`, target: '_blank', rel: 'noopener' }, 'OSM')))))),
    el('div', { class: 'city-meta' }, t('dual.scaleNote'), el('br'), t('city.osmDate', { date: osmDateText(s) })));
  }
  list.forEach((x, i) => {
    const note = territoryNote(x);
    if (note) head.append(el('div', { class: 'mode-note' }, s2 ? `${names[i]}: ${note}` : note));
  });
  renderPopulationPanel(list, names);
  renderBudgetPanel(list, names);
  renderSettlements(list, names);
  renderUnitToggle($('#unitToggleMap'), [['pct', t('unit.pctArea')], ['km2', t('unit.km2')]]);
  $('#subPctToggle').hidden = state.unit === 'km2'; // only meaningful for percentages
  $('#subPctCheckbox').checked = state.subPctOfCat;

  // ---- legend
  const legend = $('#legend');
  legend.innerHTML = '';
  legend.classList.toggle('dual', !!s2);
  const metricOf = (x) => (state.unit === 'km2' ? x.area_m2 : x.pct);
  const allCats = list.flatMap((x) => x.categories);
  const maxVal = Math.max(...allCats.map(metricOf), 1e-9);
  if (s2) {
    legend.append(el('div', { class: 'legend-row legend-head' }, el('span'), el('span'),
      ...list.map((x, i) => el('div', { class: 'value' }, el('span', { class: `city-key k${i}` }), colNames[i]))));
  }
  const bars = (vals, color, max = maxVal) => el('div', { class: 'bars' }, vals.map((v, i) =>
    el('div', { class: 'bar' }, el('span', { class: `k${i}`, style: `width:${(100 * v) / max}%;--c:${color}` }))));
  for (const c of s.categories) {
    const def = catDef(c.id);
    const cs = list.map((x) => x.categories.find((y) => y.id === c.id));
    const off = state.hidden.has(c.id);
    const open = state.expanded.has(c.id);
    const swatch = el('button', {
      class: 'swatch' + (off ? ' off' : ''), style: `background:${def.color}`, title: off ? t('legend.show') : t('legend.hide'),
      onclick: () => { off ? state.hidden.delete(c.id) : state.hidden.add(c.id); applyVisibility(); renderSidebar(); },
    });
    const subIds = def.subcategories.map((x) => x.id).filter((id) => cs.some((cc) => cc.subcategories.find((z) => z.id === id).area_m2 > 0));
    const row = el('div', { class: 'legend-row' }, swatch,
      el('div', { class: 'label' },
        el('div', { class: 'name' },
          subIds.length > 1 ? el('button', { class: 'expander', onclick: () => { open ? state.expanded.delete(c.id) : state.expanded.add(c.id); renderSidebar(); } }, open ? '▾' : '▸') : null,
          label(def)),
        bars(cs.map(metricOf), def.color)),
      ...cs.map((cc) => el('div', { class: 'value' }, valueText(cc.area_m2, cc.pct))));
    row.addEventListener('mousemove', (ev) => showTip(ev, `<b>${label(def)}</b>` + cs.map((cc, i) =>
      `<br>${s2 ? names[i] + ': ' : ''}${fmtKm2(cc.area_m2)} · ${fmtPct(cc.pct)} ${t('tip.ofCity')} · ${t('tip.features', { n: fmtInt(cc.feature_count) })}`).join('')));
    row.addEventListener('mouseleave', hideTip);
    legend.append(row);
    if (open && subIds.length > 1) {
      const sub = el('div', { class: 'subrows' });
      // value shown for a sub-category of city i: km², % of its category, or % of the city
      const subPct = (x, i) => (state.subPctOfCat ? (100 * x.area_m2) / Math.max(cs[i].area_m2, 1) : x.pct);
      const subMetric = (x, i) => (state.unit === 'km2' ? x.area_m2 : subPct(x, i));
      // sub-category bars are scaled within their category, so small types stay visible
      const subMax = Math.max(...subIds.flatMap((sid) => cs.map((cc, i) => subMetric(cc.subcategories.find((z) => z.id === sid), i))), 1e-9);
      for (const sid of subIds) {
        const key = `${c.id}/${sid}`;
        const sd = subDef(c.id, sid);
        const xs = cs.map((cc) => cc.subcategories.find((z) => z.id === sid));
        const soff = state.hiddenSub.has(key);
        const sr = el('div', { class: 'legend-row' },
          el('button', {
            class: 'swatch' + (soff ? ' off' : ''), style: `background:${sd.color}`, title: t('legend.subToggle'),
            onclick: () => { soff ? state.hiddenSub.delete(key) : state.hiddenSub.add(key); applyVisibility(); renderSidebar(); },
          }),
          el('div', { class: 'label' }, el('div', { class: 'name' }, label(sd)), s2 ? bars(xs.map(subMetric), sd.color, subMax) : null),
          ...xs.map((x, i) => el('div', { class: 'value' }, valueText(x.area_m2, subPct(x, i)))));
        sr.addEventListener('mousemove', (ev) => showTip(ev, `<b>${label(sd)}</b>` + xs.map((x, i) =>
          `<br>${s2 ? names[i] + ': ' : ''}${fmtKm2(x.area_m2)} · ${fmtPct(x.pct)} ${t('tip.ofCity')} · ` +
          `${num((100 * x.area_m2) / Math.max(cs[i].area_m2, 1), 1)}% ${t('tip.ofCat', { cat: label(def).toLowerCase() })}`).join('')));
        sr.addEventListener('mouseleave', hideTip);
        sub.append(sr);
      }
      legend.append(sub);
    }
  }
  legend.append(el('div', { class: 'small', style: 'margin-top:6px' }, t('legend.note')));

  // ---- buildings
  const bp = $('#buildingPanel');
  bp.innerHTML = '';
  const bRows = [
    [t('b.count'), (b) => fmtInt(b.count)],
    [t('b.footprint'), (b) => fmtKm2(b.footprint_m2)],
    [t('b.mean'), (b) => `${fmtInt(b.mean_footprint_m2)} ${t('units.m2')}`],
    [t('b.unknown'), (b) => {
      const unk = b.by_subcategory.unknown || { count: 0, area_m2: 0 };
      return t('b.unknownVal', { n: fmtInt(unk.count), pct: num((100 * unk.area_m2) / Math.max(b.footprint_m2, 1), 1) });
    }],
    [t('b.secondary'), (b) => fmtInt(b.classification_basis.secondary_tag || 0)],
    [t('b.levels'), (b) => num(b.levels_tagged_pct, 1) + '%'],
  ];
  bp.append(el('div', { class: 'panel' },
    el('h3', {}, t('b.title')),
    el('div', { class: 'kv' + (s2 ? ' kv3' : '') },
      s2 ? [el('span'), ...list.map((x, i) => el('span', { class: 'v head' }, el('span', { class: `city-key k${i}` }), colNames[i]))] : null,
      bRows.flatMap(([k, f]) => [el('span', {}, k), ...list.map((x) => el('span', { class: 'v' }, f(x.buildings)))]))));

  // ---- validation (one block per city; collapsed in split mode)
  const vp = $('#validationPanel');
  vp.innerHTML = '';
  for (const x of list) {
    const v = x.validation;
    if (!v) continue;
    const checks = el('ul', { class: 'checks' }, v.checks.map((c) =>
      el('li', {}, el('span', {}, el('span', { class: `badge ${c.status}` }, t(`status.${c.status}`))),
        el('span', {}, checkMessage(c, num)))));
    const title = [`${t('q.title')}${s2 ? ' — ' + names[list.indexOf(x)] : ''} `, el('span', { class: `badge ${v.status}` }, t(`status.${v.status}`))];
    vp.append(s2
      ? el('details', { class: 'panel' }, el('summary', {}, el('h3', { style: 'display:inline' }, ...title)), checks)
      : el('div', { class: 'panel' }, el('h3', {}, ...title), checks));
  }
}

// ------------------------------------------------------------------ compare
function compareData(cityStats) {
  // returns [{id,label,color,area,pct,count,catArea?}] for the current breakdown
  if (state.breakdown === 'categories') {
    return cityStats.categories.map((c) => ({
      id: c.id, label: label(catDef(c.id)), color: catDef(c.id).color, area: c.area_m2, pct: c.pct, count: c.feature_count,
    }));
  }
  const cat = cityStats.categories.find((c) => c.id === state.breakdown);
  return cat.subcategories.map((x) => ({
    id: x.id, label: label(subDef(cat.id, x.id)), color: x.color, area: x.area_m2, pct: x.pct, count: x.feature_count, catArea: cat.area_m2,
  }));
}

/** Items (categories or sub-categories) of the current breakdown, from index.json. */
function breakdownDefs() {
  return state.breakdown === 'categories' ? state.index.categories : catDef(state.breakdown).subcategories;
}

function toggleFocus(id) {
  state.focus = state.focus === id ? null : id;
  renderCompare();
}

// ---- city filter (multi-select)
function compareCityIds() {
  const all = state.index.cities.map((c) => c.id);
  if (!state.compareCities) return all;
  return all.filter((id) => state.compareCities.includes(id)); // keep index order
}

function saveCompareCities() {
  try { localStorage.setItem('compareCities', JSON.stringify(state.compareCities)); } catch { /* storage unavailable */ }
  writeHash();
}

function loadCompareCities(fromHash) {
  const known = new Set(state.index.cities.map((c) => c.id));
  let ids = fromHash;
  if (!ids) {
    try { ids = JSON.parse(localStorage.getItem('compareCities') || 'null'); } catch { ids = null; }
  }
  if (Array.isArray(ids)) {
    const valid = ids.filter((id) => known.has(id));
    if (valid.length) state.compareCities = valid;
  }
}

function renderCityFilter() {
  const ids = compareCityIds();
  const total = state.index.cities.length;
  $('#cityFilterBtn').textContent = t('cf.button', { n: ids.length, total }) + ' ▾';
  const q = $('#cityFilterSearch').value.trim().toLowerCase();
  const list = $('#cityFilterList');
  list.innerHTML = '';
  const matches = state.index.cities.filter((c) =>
    !q || c.name.toLowerCase().includes(q) || (c.name_local || '').toLowerCase().includes(q));
  const setSelection = (cur) => { state.compareCities = [...cur]; saveCompareCities(); renderCompare(); };
  for (const { group, cities } of citiesByGroup(matches)) {
    if (label(group)) {
      // clicking a group header selects the whole group, or clears it if it is fully selected
      const allOn = cities.every((c) => ids.includes(c.id));
      list.append(el('button', {
        type: 'button', class: 'cf-group', title: t(allOn ? 'cf.groupNone' : 'cf.groupAll'),
        onclick: () => {
          const cur = new Set(compareCityIds());
          for (const c of cities) allOn ? cur.delete(c.id) : cur.add(c.id);
          setSelection(cur);
        },
      }, label(group), el('span', { class: 'small' }, `${cities.filter((c) => ids.includes(c.id)).length}/${cities.length}`)));
    }
    for (const c of cities) appendCityItem(c);
  }
  function appendCityItem(c) {
    const box = el('input', { type: 'checkbox', value: c.id });
    box.checked = ids.includes(c.id);
    box.addEventListener('change', () => {
      const cur = new Set(compareCityIds());
      box.checked ? cur.add(c.id) : cur.delete(c.id);
      state.compareCities = [...cur];
      saveCompareCities();
      renderCompare();
    });
    const md = c.modes?.[state.territory];
    const areaKm2 = md && !['not_computed'].includes(md.status) ? md.area_km2 : c.area_km2;
    list.append(el('label', { class: 'cf-item' }, box, el('span', {}, cityName(c)),
      el('span', { class: 'small' }, `${num(areaKm2, 0)} ${t('units.km2')}`)));
  }
  if (!matches.length) list.append(el('div', { class: 'small', style: 'padding:6px' }, t('cf.noMatch')));
}

function initCityFilter() {
  const btn = $('#cityFilterBtn'), panel = $('#cityFilterPanel');
  const setOpen = (open) => {
    panel.hidden = !open;
    btn.setAttribute('aria-expanded', open);
    if (open) { renderCityFilter(); $('#cityFilterSearch').focus(); }
  };
  btn.addEventListener('click', (e) => { e.stopPropagation(); setOpen(panel.hidden); });
  panel.addEventListener('click', (e) => e.stopPropagation());
  document.addEventListener('click', () => setOpen(false));
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') setOpen(false); });
  $('#cityFilterSearch').addEventListener('input', renderCityFilter);
  $('#cityFilterAll').addEventListener('click', () => {
    state.compareCities = state.index.cities.map((c) => c.id); saveCompareCities(); renderCompare();
  });
  $('#cityFilterNone').addEventListener('click', () => {
    state.compareCities = []; saveCompareCities(); renderCompare();
  });
}

// ---- chart
async function renderCompare() {
  const ids = compareCityIds();
  const all = await Promise.all(ids.map(loadStats));
  await loadDemography();
  await loadBudgets();
  // two screens: land structure (categories) and budgets & population (finance)
  const finance = state.view === 'finance';
  $('#compareTitle').textContent = t(finance ? 'cmp.titleFinance' : 'cmp.title');
  if (['population', 'budgetInc', 'budgetExp'].includes(state.breakdown)) state.breakdown = 'categories';
  if (finance && state.financeBreakdown !== 'population' && !budgets.years.length) state.financeBreakdown = 'population';
  const show = finance ? state.financeBreakdown : null;
  const budgetKind = { budgetInc: 'inc', budgetExp: 'exp' }[show];
  const unitOpts = [['pct', t('unit.pctCity')], ['km2', t('unit.km2abs')]];
  if (state.breakdown !== 'categories' && state.breakdown !== 'population') {
    unitOpts.push(['pctcat', t('unit.pctOf', { what: label(catDef(state.breakdown)).toLowerCase() })]);
  }
  if (state.unit === 'pctcat' && state.breakdown === 'categories') state.unit = 'pct';
  if (show === 'population') renderPopMetricToggle();
  else if (!finance) renderUnitToggle($('#unitToggleCompare'), unitOpts);
  renderTerritoryToggles();
  renderCityFilter();

  const sel = $('#compareBreakdown');
  sel.previousElementSibling.textContent = t(finance ? 'cmp.show' : 'cmp.breakdown');
  const selKey = `${getLang()}/${finance ? 'finance' : 'land'}`;
  if (sel.dataset.key !== selKey) {
    sel.innerHTML = '';
    if (finance) {
      if (budgets.years.length) {
        sel.append(el('option', { value: 'budgetInc' }, t('cmp.budgetInc')), el('option', { value: 'budgetExp' }, t('cmp.budgetExp')));
      }
      if (demoYears().length) sel.append(el('option', { value: 'population' }, t('cmp.population')));
    } else {
      sel.append(el('option', { value: 'categories' }, t('cmp.all')));
      for (const c of state.index.categories) {
        if (c.subcategories.length > 1) sel.append(el('option', { value: c.id }, t('cmp.byType', { cat: label(c) })));
      }
    }
    sel.dataset.key = selKey;
  }
  if (!sel.dataset.bound) {
    sel.addEventListener('change', () => {
      if (state.view === 'finance') { state.financeBreakdown = sel.value; state.budgetFocus = null; } else { state.breakdown = sel.value; state.focus = null; }
      writeHash();
      renderCompare();
    });
    sel.dataset.bound = '1';
  }
  sel.value = finance ? show : state.breakdown;
  if (show === 'population') {
    renderPopulationCompare(all);
    return;
  }
  if (budgetKind) {
    renderBudgetCompare(all, budgetKind);
    return;
  }

  const defs = breakdownDefs();
  if (state.focus && !defs.some((d) => d.id === state.focus)) state.focus = null;
  const focusDef = state.focus ? defs.find((d) => d.id === state.focus) : null;

  // focus bar + hint
  const fb = $('#compareFocus');
  fb.innerHTML = '';
  if (focusDef) {
    fb.append(el('span', { class: 'focus-chip', style: `--c:${focusDef.color}` },
      el('i'), t('cmp.focus', { cat: label(focusDef) }),
      el('button', { type: 'button', title: t('cmp.focusClear'), 'aria-label': t('cmp.focusClear'), onclick: () => toggleFocus(state.focus) }, '✕')));
  }
  $('#compareHint').textContent = focusDef ? t('cmp.hint.focus', { cat: label(focusDef) })
    : (state.unit === 'km2' ? t('cmp.hint.km2')
      : state.unit === 'pctcat' ? t('cmp.hint.pctcat')
      : state.breakdown === 'categories' ? t('cmp.hint.pct') : t('cmp.hint.pctSub')) + ' ' + t('cmp.focusHint');

  const chart = $('#compareChart');
  chart.innerHTML = '';
  if (!all.length) {
    chart.append(el('p', { class: 'hint' }, t('cmp.noCities')));
    $('#compareLegend').innerHTML = '';
    $('#compareTable').innerHTML = '';
    return;
  }

  let rows = all.map((s) => {
    const items = compareData(s);
    const total = items.reduce((a, x) => a + x.area, 0);
    return { s, items, total };
  });
  // segment width (% of the bar track) and the share shown as label
  const share = (x, r) => (state.unit === 'pctcat' ? (100 * x.area) / Math.max(r.total, 1) : x.pct);
  const metric = (x, r) => (state.unit === 'km2' ? x.area : share(x, r));
  if (focusDef) {
    rows.sort((a, b) => metric(b.items.find((x) => x.id === state.focus), b) - metric(a.items.find((x) => x.id === state.focus), a));
  }
  const maxTotal = Math.max(...rows.map((r) => (state.breakdown === 'categories' ? r.s.area.boundary_m2 : r.total)));
  // focus mode: only the focused item is drawn, scaled so the largest city fills the track
  const focusMax = focusDef
    ? Math.max(...rows.map((r) => metric(r.items.find((x) => x.id === state.focus), r)), 1e-9) : 0;

  for (const r of rows) {
    const { s, items, total } = r;
    const stack = el('div', { class: 'stack' + (focusDef ? ' focused' : '') });
    let barWidth = 100;
    if (state.unit === 'km2' && !focusDef) barWidth = (100 * (state.breakdown === 'categories' ? s.area.boundary_m2 : total)) / maxTotal;
    stack.style.width = barWidth + '%';
    const shown = focusDef ? items.filter((x) => x.id === state.focus) : items;
    for (const x of shown) {
      if (x.area <= 0) continue;
      const w = focusDef ? (100 * metric(x, r)) / focusMax
        : state.unit === 'pctcat' || state.unit === 'km2' ? (100 * x.area) / Math.max(total, 1) : x.pct;
      const text = focusDef ? (state.unit === 'km2' ? fmtKm2(x.area) : fmtPct(share(x, r)))
        : state.unit === 'km2' ? num(km2(x.area), 0) : num(share(x, r), 0) + '%';
      const seg = el('div', {
        class: 'seg' + (focusDef ? ' active' : ''),
        style: `width:${w}%;background:${x.color}`,
        role: 'button', tabindex: '0', 'aria-label': `${cityName(s.city)}: ${x.label}`,
      }, el('span', { style: isLight(x.color) ? 'color:#333;text-shadow:none' : '' }, w > 6 ? text : ''));
      seg.addEventListener('mousemove', (ev) => showTip(ev,
        `<b>${cityName(s.city)} — ${x.label}</b><br>${fmtKm2(x.area)}<br>${fmtPct(x.pct)} ${t('cmp.ofCityArea')}` +
        (x.catArea ? `<br>${num((100 * x.area) / Math.max(x.catArea, 1), 1)}% ${t('cmp.ofCategory')}` : '') +
        `<br>${t('tip.features', { n: fmtInt(x.count) })}`));
      seg.addEventListener('mouseleave', hideTip);
      seg.addEventListener('click', () => { hideTip(); toggleFocus(x.id); });
      seg.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleFocus(x.id); } });
      stack.append(seg);
    }
    let totalText;
    if (focusDef) {
      const f = items.find((x) => x.id === state.focus);
      totalText = el('span', { class: 'focus-value' },
        state.unit === 'km2' ? fmtKm2(f.area) : fmtPct(share(f, r)),
        el('span', { class: 'small' }, ' · ' + (state.unit === 'km2' ? fmtPct(share(f, r)) : fmtKm2(f.area))));
    } else {
      totalText = state.breakdown === 'categories' ? `${num(s.area.boundary_km2, 0)} ${t('units.km2')}`
        : `${num(km2(total), 1)} ${t('units.km2')} · ${num((100 * total) / s.area.boundary_m2, 1)}%`;
    }
    chart.append(el('div', { class: 'chart-row' },
      el('button', {
        type: 'button', class: 'city link', title: t('cmp.openMap', { city: cityName(s.city) }),
        onclick: () => { state.city = s.city.id; if (state.city2 === s.city.id) state.city2 = null; switchView('map'); },
      }, cityName(s.city), territoryNote(s) ? el('span', { class: 'terr-mark', title: territoryNote(s) }, ' ⓘ') : null),
      el('div', {}, stack),
      el('div', { class: 'total' }, totalText)));
  }

  // residential / industrial land exclude the buildings on them (priority painting)
  $('#compareNote').textContent = t('cmp.landNote', {
    res: label(catDef('residential')), ind: label(catDef('industrial')), bld: label(catDef('buildings')),
  });

  // legend (click = focus)
  const lg = $('#compareLegend');
  lg.innerHTML = '';
  for (const d of defs) {
    if (!rows.some((r) => (r.items.find((x) => x.id === d.id)?.area || 0) > 0)) continue;
    const isFocus = state.focus === d.id;
    lg.append(el('button', {
      type: 'button', class: 'legend-item' + (isFocus ? ' active' : '') + (focusDef && !isFocus ? ' dim' : ''),
      'aria-pressed': isFocus, onclick: () => toggleFocus(d.id),
    }, el('i', { style: `background:${d.color}` }), label(d)));
  }

  // table (collapsed by default; rendered only when opened)
  const details = $('#compareTableDetails');
  if (!details.dataset.bound) {
    details.addEventListener('toggle', () => { if (details.open) renderCompareTable(); });
    details.dataset.bound = '1';
  }
  if (details.open) renderCompareTable(all);
  else $('#compareTable').innerHTML = '';
}

function renderPopMetricToggle() {
  const box = $('#unitToggleCompare');
  box.innerHTML = '';
  for (const [id, text] of [['pop', t('demo.population')], ['density', `${t('demo.density')}, ${t('demo.perKm2')}`]]) {
    box.append(el('button', {
      class: state.popMetric === id ? 'active' : '',
      onclick: () => { state.popMetric = id; renderCompare(); },
    }, text));
  }
}

/** Compare screen, "Population" breakdown: one bar per city (city + rest of the territory), or density. */
function renderPopulationCompare(all) {
  const density = state.popMetric === 'density';
  $('#compareFocus').innerHTML = '';
  $('#compareFocus').append(financeYearControls());
  $('#compareHint').textContent = t(density ? 'cmp.hint.density' : 'cmp.hint.pop');
  const chart = $('#compareChart');
  chart.innerHTML = '';
  if (!all.length) {
    chart.append(el('p', { class: 'hint' }, t('cmp.noCities')));
    $('#compareLegend').innerHTML = '';
    $('#compareTable').innerHTML = '';
    return;
  }
  const rows = all.map((s) => ({ s, p: popOf(s) }));
  const value = (r) => (r.p ? (density ? r.p.density : r.p.pop) : -1);
  rows.sort((a, b) => value(b) - value(a));
  const max = Math.max(...rows.map(value), 1);
  const CITY = '#4a5a6a', REST = '#a9b4bf';
  for (const r of rows) {
    const { s, p } = r;
    const stack = el('div', { class: 'stack' });
    if (p) {
      stack.style.width = `${(100 * value(r)) / max}%`;
      const parts = density ? [[p.pop, CITY, t('demo.density')]]
        : [[p.cityPop, CITY, t('demo.cityOnly')], [p.pop - p.cityPop, REST, restLabel(s._mode)]];
      const sum = parts.reduce((a, x) => a + x[0], 0);
      for (const [v, color, name] of parts) {
        if (v <= 0) continue;
        const seg = el('div', { class: 'seg', style: `width:${(100 * v) / Math.max(sum, 1)}%;background:${color}` });
        seg.addEventListener('mousemove', (ev) => showTip(ev, `<b>${cityName(s.city)}</b><br>` + (density
          ? `${fmtInt(p.density)} ${t('demo.perKm2')}<br>${fmtInt(p.pop)} ${t('demo.people')} / ${num(s.area.boundary_km2, 1)} ${t('units.km2')}`
          : `${name}: ${fmtInt(v)} ${t('demo.people')}<br>${t('demo.population')}: ${fmtInt(p.pop)}`)));
        seg.addEventListener('mouseleave', hideTip);
        stack.append(seg);
      }
    }
    const note = territoryNote(s) || (p ? demoEstimateNote(cityById(s.city.id)) : t('demo.noData'));
    chart.append(el('div', { class: 'chart-row' },
      el('button', {
        type: 'button', class: 'city link', title: t('cmp.openMap', { city: cityName(s.city) }),
        onclick: () => { state.city = s.city.id; if (state.city2 === s.city.id) state.city2 = null; switchView('map'); },
      }, cityName(s.city), note ? el('span', { class: 'terr-mark', title: note }, ' ⓘ') : null),
      el('div', {}, stack),
      el('div', { class: 'total' }, p ? (density ? `${fmtInt(p.density)} ${t('demo.perKm2')}` : fmtInt(p.pop)) : '—')));
  }
  const lg = $('#compareLegend');
  lg.innerHTML = '';
  if (!density) {
    const modes = new Set(all.map((s) => s._mode).filter((m) => m !== 'city'));
    lg.append(el('span', { class: 'legend-item' }, el('i', { style: `background:${CITY}` }), t('demo.cityOnly')));
    for (const m of modes) lg.append(el('span', { class: 'legend-item' }, el('i', { style: `background:${REST}` }), restLabel(m)));
  }
  $('#compareNote').textContent = `${demoSource()}. ${t('cmp.popNote')}`;
  const details = $('#compareTableDetails');
  if (!details.dataset.bound) {
    details.addEventListener('toggle', () => { if (details.open) renderCompareTable(); });
    details.dataset.bound = '1';
  }
  if (details.open) renderCompareTable(all);
  else $('#compareTable').innerHTML = '';
}

function renderPopulationTable(all) {
  const head = el('tr', {}, ['cmp.city', 'demo.population', 'demo.cityOnly', 'about.area', 'demo.density'].map((k) => el('th', {}, t(k))));
  const body = all.map((s) => {
    const p = popOf(s);
    return el('tr', {}, el('td', {}, cityName(s.city)),
      el('td', {}, p ? fmtInt(p.pop) : '—'), el('td', {}, p ? fmtInt(p.cityPop) : '—'),
      el('td', {}, num(s.area.boundary_km2, 1)), el('td', {}, p ? fmtInt(p.density) : '—'));
  });
  $('#compareTable').innerHTML = '';
  $('#compareTable').append(el('table', {}, el('thead', {}, head), el('tbody', {}, body)));
}

async function renderCompareTable(statsList) {
  const all = statsList || await Promise.all(compareCityIds().map(loadStats));
  const fb = state.view === 'finance' ? state.financeBreakdown : null;
  if (fb === 'budgetInc' || fb === 'budgetExp') {
    renderBudgetTable(all, fb === 'budgetInc' ? 'inc' : 'exp');
    return;
  }
  if (fb === 'population') {
    renderPopulationTable(all);
    return;
  }
  const head = el('tr', {}, el('th', {}, state.breakdown === 'categories' ? t('cmp.category') : label(catDef(state.breakdown))),
    ...all.flatMap((s) => [el('th', {}, `${cityName(s.city)}, ${t('units.km2')}`), el('th', {}, '%')]));
  const body = [];
  const addRow = (text, cells, cls = '') => body.push(el('tr', { class: cls }, el('td', {}, text), ...cells));
  const cells = (x, d = 2) => [el('td', {}, num(km2(x.area_m2), d)), el('td', {}, num(x.pct, 2))];
  const findSub = (s, catId, subId) => s.categories.find((y) => y.id === catId).subcategories.find((z) => z.id === subId);
  if (state.breakdown === 'categories') {
    for (const c of state.index.categories) {
      addRow(label(c), all.flatMap((s) => cells(s.categories.find((y) => y.id === c.id))), state.focus === c.id ? 'hl' : '');
      if (c.subcategories.length === 1) continue;
      for (const sub of c.subcategories) {
        if (!all.some((s) => findSub(s, c.id, sub.id).area_m2 > 0)) continue;
        addRow(label(sub), all.flatMap((s) => cells(findSub(s, c.id, sub.id))), 'sub');
      }
    }
    addRow(t('cmp.total'), all.flatMap((s) => [el('td', {}, num(s.area.boundary_km2, 2)), el('td', {}, num(100, 2))]));
  } else {
    for (const sub of catDef(state.breakdown).subcategories) {
      addRow(label(sub), all.flatMap((s) => cells(findSub(s, state.breakdown, sub.id), 3)), state.focus === sub.id ? 'hl' : '');
    }
  }
  $('#compareTable').innerHTML = '';
  $('#compareTable').append(el('table', {}, el('thead', {}, head), el('tbody', {}, body)));
}

// ------------------------------------------------------------------ about
/** Sub-pages of the Method & data page: an <h2 data-page="id"> in about*.html starts a new one. */
const ABOUT_PAGES = ['overview', 'area', 'population', 'usage', 'quality'];

async function renderAbout() {
  const a = $('#aboutContent');
  const lang = getLang();
  if (a.dataset.loaded !== lang) {
    try {
      const r = await fetch(lang === 'uk' ? 'about.uk.html' : 'about.html');
      if (!r.ok) throw new Error(String(r.status));
      a.innerHTML = await r.text();
      a.dataset.loaded = lang;
      paginateAbout(a);
      fillAboutCities();
    } catch { a.textContent = t('about.error'); return; }
  }
  showAboutPage(state.aboutPage);
}

/** Wrap the loaded page into one <section> per sub-page, with a navigation bar under the title. */
function paginateAbout(a) {
  const h1 = a.querySelector('h1');
  const sections = {};
  let page = ABOUT_PAGES[0];
  for (const node of [...a.childNodes]) {
    if (node === h1) continue;
    if (node.nodeType === 1 && node.dataset.page) page = node.dataset.page;
    sections[page] ??= el('section', { class: 'about-page', 'data-page': page });
    sections[page].append(node);
  }
  const ids = ABOUT_PAGES.filter((p) => sections[p]);
  const nav = el('nav', { class: 'about-nav', 'aria-label': t('about.nav') },
    ids.map((p) => el('button', { type: 'button', 'data-page': p, onclick: () => showAboutPage(p) }, t(`about.page.${p}`))));
  // previous / next links at the bottom of every sub-page
  ids.forEach((p, i) => {
    const pager = el('div', { class: 'about-pager' },
      i > 0 ? el('button', { type: 'button', onclick: () => showAboutPage(ids[i - 1]) }, `← ${t(`about.page.${ids[i - 1]}`)}`) : el('span'),
      i < ids.length - 1 ? el('button', { type: 'button', onclick: () => showAboutPage(ids[i + 1]) }, `${t(`about.page.${ids[i + 1]}`)} →`) : el('span'));
    sections[p].append(pager);
  });
  a.innerHTML = '';
  a.append(...[h1, nav, ...ids.map((p) => sections[p])].filter(Boolean));
}

function showAboutPage(page) {
  const a = $('#aboutContent');
  const pages = [...a.querySelectorAll('.about-page')];
  if (!pages.length) return;
  if (!pages.some((s) => s.dataset.page === page)) page = pages[0].dataset.page;
  const changed = page !== state.aboutPage;
  state.aboutPage = page;
  for (const s of pages) s.hidden = s.dataset.page !== page;
  a.querySelectorAll('.about-nav button').forEach((b) => b.classList.toggle('active', b.dataset.page === page));
  if (changed) a.scrollTop = 0;
  writeHash();
}

/** City table on the Method & data page, generated from index.json so it never goes stale. */
function fillAboutCities() {
  const box = $('#aboutCities');
  if (!box) return;
  const uk = getLang() === 'uk';
  // notes go on their own full-width line under each city, so the table also fits phone screens
  const cityRows = (c) => {
    const note = (uk ? c.notes_uk : c.notes) || c.notes || '';
    return [
      el('tr', { class: note ? 'has-note' : '' },
        el('td', {}, el('strong', {}, cityName(c))),
        el('td', {}, `${num(c.area_km2, 0)} ${t('units.km2')}`),
        el('td', {}, c.osm_relation
          ? el('a', { href: `https://www.openstreetmap.org/relation/${c.osm_relation}`, target: '_blank', rel: 'noopener' }, `r${c.osm_relation}`)
          : '—'),
        el('td', {}, c.osm_timestamp ? new Date(c.osm_timestamp).toLocaleDateString(locale()) : '—')),
      note ? el('tr', { class: 'note-row' }, el('td', { colspan: '4' }, note)) : null,
    ].filter(Boolean);
  };
  const rows = citiesByGroup().flatMap(({ group, cities }) => [
    label(group) ? el('tr', { class: 'group-row' }, el('th', { colspan: '4' }, label(group))) : null,
    ...cities.flatMap(cityRows),
  ].filter(Boolean));
  box.innerHTML = '';
  box.append(el('div', { class: 'table-wrap' }, el('table', { class: 'cities-table' },
    el('thead', {}, el('tr', {}, ['about.city', 'about.area', 'about.relation', 'about.osmDate'].map((k) => el('th', {}, t(k))))),
    el('tbody', {}, rows))));
}

// ------------------------------------------------------------------ population of cities (by drive time)
/*
 * data/agglomeration.json (python -m urbanfp agglomeration): drive times (tenths of a minute) from every city
 * to every settlement within 3 h, plus the settlements' population per year. Joining is done here so the
 * threshold and the year switch instantly.
 */
let agg = null;
let aggReach = null;   // centre id -> Map(settlement index -> tenths of a minute)
const popView = { map: null, ready: null, result: null, frame: null };
// clearly distinct hues only: neighbouring agglomerations get different ones (assignAggColors)
const POP_COLORS = ['#2f6db5', '#d1495b', '#2e9d6a', '#e08a1e', '#7b52ae', '#1c9aa8', '#6c8a1f', '#8c6d3f'];
const AGG_ADJ_KM = 30;  // agglomerations whose settlements come this close count as neighbours

async function loadAgglomeration() {
  if (agg) return agg;
  agg = await getJSON(`${DATA}/agglomeration.json`);
  aggReach = {};
  for (const [id, list] of Object.entries(agg.reach)) aggReach[id] = new Map(list);
  // any multiple of POP_STEP up to the computed maximum (the slider); the buttons are shortcuts
  const th = state.popThreshold;
  if (!(Number.isInteger(th) && th >= 0 && th <= aggPageMax() && th % POP_STEP === 0)) state.popThreshold = 30;
  return agg;
}

const POP_STEP = 5;  // slider step, minutes
// drive times reach 6 h (region modelling); the Агломерації page stays within 3 h
const AGG_PAGE_MAX_MIN = 180;
const aggPageMax = () => Math.min(agg.max_min, AGG_PAGE_MAX_MIN);
const fmtThreshold = (m) => (m === 0 ? t('pop.cityOnly')
  : m < 60 ? `${m} ${t('set.min')}`
    : m % 30 === 0 ? `${num(m / 60, m % 60 ? 1 : 0)} ${t('pop.hour')}`
      : `${Math.floor(m / 60)} ${t('pop.hour')} ${m % 60} ${t('set.min')}`);

/** Set the drive-time threshold and redraw; slider moves are coalesced to one redraw per frame. */
function setPopThreshold(m, final = true) {
  state.popThreshold = m;
  if (final) writeHash();
  if (popView.frame) return;
  popView.frame = requestAnimationFrame(async () => {
    try { await renderPopulationView(); } finally { popView.frame = null; }
  });
}

/** A centre joins a larger one only if the larger city is more than this many times bigger. */
const ABSORB_RATIO = 2;
/**
 * Join settlements to centres for threshold `T` (minutes) and `year`. Centres from the largest city down;
 * a centre within T of an active centre more than ABSORB_RATIO times its size becomes inactive and joins it
 * (the fastest reached such centre). Centres of comparable size both stay active. Each settlement joins the
 * active centre it is reached from fastest (ties: the larger one).
 */
function computeAgglomeration(T, year) {
  const S = agg.settlements;
  const pop = S.pop[year] || [];
  const lim = T * 10;
  const centres = agg.centres.map((c) => {
    const cityPop = c.settlement != null ? pop[c.settlement] : null;
    // cities not processed yet for the map (map_only) are known to the Агломерації page only
    const city = cityById(c.id) || { id: c.id, name: c.name, name_local: c.name_local };
    return { ...c, city, cityPop, total: cityPop || 0, n: 0, active: false, absorbedBy: null, time: null };
  });
  const ranked = centres.filter((c) => c.cityPop != null).sort((a, b) => b.cityPop - a.cityPop);
  const active = [];
  for (const c of ranked) {
    let host = null;
    for (const a of T > 0 ? active : []) {
      const tt = aggReach[a.id]?.get(c.settlement) ?? Infinity;
      if (tt <= lim && a.cityPop > ABSORB_RATIO * c.cityPop && (!host || tt < aggReach[host.id].get(c.settlement))) host = a;
    }
    if (host) { c.absorbedBy = host.id; c.time = aggReach[host.id].get(c.settlement) / 10; } else { c.active = true; active.push(c); }
  }
  const owner = new Int16Array(S.code.length).fill(-1);
  const best = new Float32Array(S.code.length).fill(Infinity);
  active.forEach((a, i) => { a.idx = i; });
  for (const a of active) { owner[a.settlement] = a.idx; best[a.settlement] = -1; }  // a city belongs to itself
  if (T > 0) {
    for (const a of active) {
      for (const [i, tt] of aggReach[a.id] || []) {
        if (tt <= lim && tt < best[i]) { best[i] = tt; owner[i] = a.idx; }
      }
    }
    // an absorbed city belongs to the centre that absorbed it, even if another active centre is closer
    const byId = Object.fromEntries(active.map((a) => [a.id, a]));
    for (const c of centres) if (c.absorbedBy) owner[c.settlement] = byId[c.absorbedBy].idx;
    for (let i = 0; i < owner.length; i++) {
      const o = owner[i];
      if (o < 0 || best[i] < 0) continue;
      active[o].total += pop[i] || 0;
      active[o].n += 1;
    }
  }
  assignAggColors(active, owner, T);
  return { centres, active, owner, pop };
}

/**
 * Colours so that neighbouring agglomerations differ: two agglomerations are neighbours when any of their
 * settlements are within AGG_ADJ_KM of each other (their centres within twice that when only cities are shown).
 * Largest first, each takes the first palette colour no neighbour has (the least used among neighbours if all
 * are taken).
 */
function assignAggColors(active, owner, T) {
  const S = agg.settlements;
  const adj = active.map(() => new Set());
  const maxKm = T > 0 ? AGG_ADJ_KM : 2 * AGG_ADJ_KM;
  // points on a grid of maxKm cells, grouped by agglomeration: cell -> Map(agglomeration -> [x, y, ...])
  const grid = new Map();
  const put = (i, o) => {
    const x = S.lon[i] * HULL_KX, y = S.lat[i] * HULL_KY;
    const key = `${Math.floor(x / maxKm)},${Math.floor(y / maxKm)}`;
    if (!grid.has(key)) grid.set(key, new Map());
    const c = grid.get(key);
    if (!c.has(o)) c.set(o, []);
    c.get(o).push(x, y);
  };
  if (T > 0) { for (let i = 0; i < owner.length; i++) if (owner[i] >= 0) put(i, owner[i]); }
  else active.forEach((a, o) => put(a.settlement, o));
  const near = (p, q) => {
    for (let i = 0; i < p.length; i += 2) {
      for (let j = 0; j < q.length; j += 2) if (Math.hypot(p[i] - q[j], p[i + 1] - q[j + 1]) <= maxKm) return true;
    }
    return false;
  };
  for (const [key, cell] of grid) {
    const [cx, cy] = key.split(',').map(Number);
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        const other = grid.get(`${cx + dx},${cy + dy}`);
        if (!other) continue;
        for (const [a, pa] of cell) {
          for (const [b, pb] of other) {
            if (a < b && !adj[a].has(b) && near(pa, pb)) { adj[a].add(b); adj[b].add(a); }
          }
        }
      }
    }
  }
  const color = new Array(active.length).fill(-1);
  const order = active.map((_, i) => i).sort((x, y) => (active[y].total - active[x].total) || (active[y].cityPop - active[x].cityPop));
  for (const o of order) {
    const used = POP_COLORS.map(() => 0);
    for (const n of adj[o]) if (color[n] >= 0) used[color[n]] += 1;
    const free = used.indexOf(0);
    color[o] = free >= 0 ? free : used.indexOf(Math.min(...used));
    active[o].color = POP_COLORS[color[o]];
  }
}

async function renderPopulationView() {
  try { await loadAgglomeration(); } catch {
    $('#popChart').innerHTML = '';
    $('#popChart').append(el('p', { class: 'hint' }, t('pop.noFile')));
    return;
  }
  const year = state.demoYear;
  const res = computeAgglomeration(state.popThreshold, year);
  popView.result = res;

  // controls
  const th = $('#popThreshold');
  th.innerHTML = '';
  for (const m of agg.thresholds_min) {
    th.append(el('button', {
      type: 'button', class: state.popThreshold === m ? 'active' : '', 'aria-pressed': state.popThreshold === m,
      onclick: () => setPopThreshold(m),
    }, fmtThreshold(m)));
  }
  const slider = $('#popSlider');
  slider.max = aggPageMax();
  slider.step = POP_STEP;
  if (document.activeElement !== slider) slider.value = state.popThreshold;
  slider.oninput = () => { $('#popSliderVal').textContent = fmtThreshold(+slider.value); setPopThreshold(+slider.value, false); };
  slider.onchange = () => setPopThreshold(+slider.value);
  $('#popSliderVal').textContent = fmtThreshold(state.popThreshold);
  const yb = $('#popYear');
  yb.innerHTML = '';
  yb.append(`${t('demo.title')}: `, demoYearControl());
  $('#popHint').textContent = state.popThreshold === 0 ? t('pop.hint.city') : t('pop.hint', { t: fmtThreshold(state.popThreshold) });
  const legend = $('#popLegend');
  legend.innerHTML = '';
  legend.append(...['pop.legend.3', 'pop.legend.2', 'pop.legend.1', 'pop.legend.0'].map((k, i) =>
    el('span', { class: `pop-legend-item cls${3 - i}` }, el('i'), t(k))));
  legend.append(el('span', { class: 'pop-legend-item outside' }, el('i'), t('pop.outsideLegend')));

  // bar chart: active centres by total population
  const rows = [...res.active].sort((a, b) => b.total - a.total);
  const max = Math.max(...rows.map((c) => c.total), 1);
  const chart = $('#popChart');
  chart.innerHTML = '';
  for (const c of rows) {
    const row = el('div', { class: 'pop-row' + (state.popSelected === c.id ? ' sel' : '') + (state.popSelected && state.popSelected !== c.id ? ' dim' : ''), 'data-id': c.id },
      el('div', { class: 'name', title: cityName(c.city) }, cityName(c.city)),
      el('div', {}, el('div', { class: 'bar', style: `width:${(100 * c.total) / max}%` },
        el('i', { style: `width:${(100 * c.cityPop) / c.total}%;background:${c.color}` }),
        el('i', { style: `width:${(100 * (c.total - c.cityPop)) / c.total}%;background:${c.color};opacity:.45` }))),
      el('div', { class: 'val' }, fmtInt(c.total)));
    const absorbed = res.centres.filter((x) => x.absorbedBy === c.id);
    row.addEventListener('mousemove', (ev) => showTip(ev, `<b>${cityName(c.city)}</b><br>${t('demo.population')}: ${fmtInt(c.total)}`
      + `<br>${t('demo.cityOnly')}: ${fmtInt(c.cityPop)}`
      + (state.popThreshold ? `<br>${t('pop.around', { t: fmtThreshold(state.popThreshold) })}: ${fmtInt(c.total - c.cityPop)} (${t('pop.nSett', { n: fmtInt(c.n) })})` : '')
      + (absorbed.length ? `<br>${t('pop.includes')}: ${absorbed.map((x) => cityName(x.city)).join(', ')}` : '')));
    row.addEventListener('mouseleave', hideTip);
    row.addEventListener('click', () => selectPopCentre(c.id));
    chart.append(row);
  }
  const inactive = res.centres.filter((c) => c.absorbedBy);
  const nodata = res.centres.filter((c) => c.cityPop == null);
  const ib = $('#popInactive');
  ib.innerHTML = '';
  if (inactive.length) {
    ib.append(el('div', {}, el('b', {}, t('pop.inactive')), ' ',
      inactive.sort((a, b) => b.cityPop - a.cityPop).map((c) => `${cityName(c.city)} → ${cityName(res.centres.find((x) => x.id === c.absorbedBy).city)} (${num(c.time, 0)} ${t('set.min')})`).join('; ')));
  }
  if (nodata.length) ib.append(el('div', {}, el('b', {}, t('pop.noDataTitle')), ' ', nodata.map((c) => cityName(c.city)).join(', ')));
  $('#popNote').textContent = t('pop.note', { max: fmtThreshold(aggPageMax()) }) + ' ' + demoSource() + '.';
  await ensurePopMap();
  updatePopMap();
}

function selectPopCentre(id) {
  state.popSelected = state.popSelected === id ? null : id;
  renderPopulationView();
}

/**
 * A map of settlements and centres (Агломерації, Моделювання регіонів): sources/layers `hull-outer` (pale outline),
 * `hull`, `sett` (settlement dots by size class; `pale` ones faded) and `centres` (circles by total population).
 * opts: centreTip(properties) and settTip(properties) return tooltip HTML; onCentreClick(id).
 */
function createAggMap(container, opts) {
  const map = new maplibregl.Map({
    container, style: BASE_STYLE(), center: [31.2, 48.6], zoom: 5.3,
    attributionControl: { compact: true }, locale: { ...MAP_LOCALE[getLang()] },
    pixelRatio: Math.min(window.devicePixelRatio || 1, 2), dragRotate: false, pitchWithRotate: false,
  });
  map.touchZoomRotate.disableRotation();
  map.addControl(new maplibregl.NavigationControl({ showCompass: false }), 'top-right');
  map.addControl(new maplibregl.ScaleControl({ unit: 'metric' }), 'bottom-left');
  const ready = new Promise((res) => map.once('load', () => {
    const empty = { type: 'FeatureCollection', features: [] };
    for (const id of ['sett', 'centres', 'hull', 'hull-outer']) map.addSource(id, { type: 'geojson', data: empty });
    const hullWidth = (k) => ['interpolate', ['linear'], ['zoom'], 5, ['case', ['get', 'sel'], 2.5 * k, 1.6 * k], 9, ['case', ['get', 'sel'], 4 * k, 2.5 * k]];
    const lineLayout = { 'line-join': 'round', 'line-cap': 'round' };
    map.addLayer({
      id: 'hull-outer', type: 'line', source: 'hull-outer', layout: lineLayout,
      paint: { 'line-color': ['get', 'color'], 'line-width': hullWidth(0.8), 'line-opacity': ['case', ['get', 'dim'], 0.1, 0.4] },
    });
    map.addLayer({
      id: 'hull', type: 'line', source: 'hull', layout: lineLayout,
      paint: { 'line-color': ['get', 'color'], 'line-width': hullWidth(1), 'line-opacity': ['case', ['get', 'dim'], 0.2, 0.9] },
    });
    // settlements by size class (POP_CLASSES): towns as circles like the centres, smaller places as dots
    const big = ['==', ['get', 'cls'], 3];
    const bySize = (town, c2, c1, c0) => ['case', big, town, ['match', ['get', 'cls'], 2, c2, 1, c1, c0]];
    const fade = ['*', ['case', ['get', 'dim'], 0.2, 1], ['case', ['get', 'pale'], 0.35, 1]];
    map.addLayer({
      id: 'sett', type: 'circle', source: 'sett',
      // dots over circles; member settlements over pale ones, pale over the grey ones
      layout: { 'circle-sort-key': ['+', ['case', ['get', 'in'], 0, -1000], ['case', ['get', 'pale'], -100, 0],
        ['case', big, ['-', 0, ['get', 'r']], ['get', 'cls']]] },
      paint: {
        'circle-color': ['get', 'color'],
        'circle-radius': ['interpolate', ['exponential', 1.6], ['zoom'],
          5, bySize(['get', 'r'], 2.2, 1.4, 0.9),
          9, bySize(['*', ['get', 'r'], 6.5], 4.5, 3, 2),
          12, bySize(['*', ['get', 'r'], 6.5], 6.5, 4.5, 3)],
        'circle-opacity': ['*', fade, bySize(0.45, 1, 0.6, 0.25)],
        'circle-stroke-color': ['get', 'color'],
        'circle-stroke-width': bySize(1.2, 0, 0, 0),
        'circle-stroke-opacity': fade,
      },
    });
    map.addLayer({
      id: 'centres', type: 'circle', source: 'centres',
      paint: {
        'circle-color': ['get', 'color'],
        'circle-opacity': ['case', ['get', 'dim'], 0.15, 0.55],
        'circle-stroke-color': ['get', 'color'],
        'circle-stroke-width': ['case', ['get', 'sel'], 3, 1.5],
        'circle-stroke-opacity': ['case', ['get', 'dim'], 0.3, 1],
        // area proportional to population; grows with zoom
        'circle-radius': ['interpolate', ['exponential', 1.6], ['zoom'], 5, ['get', 'r'], 9, ['*', ['get', 'r'], 6.5]],
      },
    });
    map.on('mousemove', 'centres', (e) => {
      map.getCanvas().style.cursor = 'pointer';
      showTip(e.originalEvent, opts.centreTip(e.features[0].properties));
    });
    map.on('mouseleave', 'centres', () => { map.getCanvas().style.cursor = ''; hideTip(); });
    map.on('click', 'centres', (e) => opts.onCentreClick(e.features[0].properties.id));
    // opts.onSettClick (optional): settlements that are cities (properties.city) are clickable
    const cityUnder = (e) => (opts.onSettClick ? e.features.find((f) => f.properties.city) : null);
    map.on('mousemove', 'sett', (e) => {
      if (map.queryRenderedFeatures(e.point, { layers: ['centres'] }).length) return;
      const city = cityUnder(e);
      map.getCanvas().style.cursor = city ? 'pointer' : '';
      showTip(e.originalEvent, opts.settTip((city || e.features[0]).properties));
    });
    map.on('mouseleave', 'sett', () => { map.getCanvas().style.cursor = ''; hideTip(); });
    map.on('click', 'sett', (e) => {
      if (map.queryRenderedFeatures(e.point, { layers: ['centres'] }).length) return;
      const city = cityUnder(e);
      if (city) opts.onSettClick(city.properties);
    });
    res();
  }));
  return { map, ready };
}

/** Tooltip head of a settlement: name and population. */
const settTipHead = (f) => `<b>${agg.settlements.name[f.i]}</b><br>${f.pop ? `${fmtInt(f.pop)} ${t('demo.people')}` : t('pop.noPop')}`;

async function ensurePopMap() {
  if (popView.map) { popView.map.resize(); return popView.ready; }
  Object.assign(popView, createAggMap('popMap', {
    centreTip: (p) => `<b>${p.name}</b><br>${state.popThreshold > 0 ? `${t('pop.agglomeration')}: ${fmtInt(p.total)}<br>` : ''}`
      + `${t('demo.cityOnly')}: ${fmtInt(p.cityPop)}`,
    settTip: (f) => `${settTipHead(f)} · ${f.in ? `${num(f.t, 0)} ${t('set.min')} → ${f.centre}` : t('pop.outside')}`,
    onCentreClick: selectPopCentre,
  }));
  return popView.ready;
}

/** Size class of a settlement on the population map: 3 = 50k+ (circle), 2 = 10–50k, 1 = 1–10k, 0 = under 1k. */
const POP_CLASSES = [1000, 10000, 50000];
const POP_OUTSIDE = '#8d9299';  // settlements outside every agglomeration
const popClass = (n) => POP_CLASSES.filter((x) => n >= x).length;

function updatePopMap() {
  const map = popView.map;
  if (!map || !map.getSource('centres')) return;
  const { active, owner, pop } = popView.result;
  const S = agg.settlements;
  const sel = state.popSelected;
  const maxTotal = Math.max(...active.map((c) => c.total), 1);
  const centres = active.map((c) => ({
    type: 'Feature', geometry: { type: 'Point', coordinates: [S.lon[c.settlement], S.lat[c.settlement]] },
    properties: {
      id: c.id, name: cityName(c.city), total: c.total, cityPop: c.cityPop, color: c.color,
      r: 34 * Math.sqrt(c.total / maxTotal), sel: sel === c.id, dim: !!sel && sel !== c.id,
    },
  })).sort((a, b) => b.properties.total - a.properties.total);  // small circles on top
  // every settlement: coloured by the centre it joined, grey when it belongs to no agglomeration
  const sett = [];
  for (let i = 0; i < owner.length; i++) {
    const o = owner[i];
    const c = o >= 0 ? active[o] : null;
    if (c?.settlement === i) continue;  // the centre's own circle
    const n = pop[i] || 0;
    sett.push({
      type: 'Feature', geometry: { type: 'Point', coordinates: [S.lon[i], S.lat[i]] },
      properties: {
        i, pop: n, cls: popClass(n), r: 34 * Math.sqrt(n / maxTotal), in: !!c,
        color: c ? c.color : POP_OUTSIDE, t: c ? (aggReach[c.id].get(i) || 0) / 10 : null,
        centre: c ? cityName(c.city) : null, dim: !!sel && sel !== c?.id, pale: false,
      },
    });
  }
  map.getSource('centres').setData({ type: 'FeatureCollection', features: centres });
  map.getSource('hull').setData({ type: 'FeatureCollection', features: aggHulls(popView.result, sel) });
  map.getSource('sett').setData({ type: 'FeatureCollection', features: sett });
}

/**
 * Outline of every agglomeration: a concave hull through its outermost points.
 * The points of an agglomeration are its settlements plus the outlines of the cities in it (the centre and the
 * cities it absorbed). They are triangulated (Delaunay); a triangle is kept when no side is longer than
 * HULL_MAX_EDGE_KM, or when all three corners lie on the outline of one city. Of the kept triangles only the
 * connected part around the centre is drawn, so detached members (a city absorbed into a distant centre, with its
 * surroundings in another agglomeration) do not stretch the outline. Holes are dropped.
 */
const HULL_MAX_EDGE_KM = 15;
const HULL_KX = Math.cos((48.5 * Math.PI) / 180) * 111.32;  // km per degree of longitude / latitude
const HULL_KY = 111.32;

/** Agglomeration outlines for the Агломерації page: the centre's and every absorbed city's outline count. */
function aggHulls(res, sel) {
  if (!res || state.popThreshold === 0) return [];
  const byId = Object.fromEntries(res.active.map((a) => [a.id, a]));
  const outlines = res.centres.map((c) => {
    const host = c.active ? c : byId[c.absorbedBy];
    return host ? { o: host.idx, key: c.id, coords: c.outline } : null;
  }).filter(Boolean);
  return withSel(hullFeatures(res.active, res.owner, outlines), sel);
}

/** Mark the selected feature and dim the others (properties.id). */
const withSel = (feats, sel) => feats.map((f) => {
  f.properties.sel = sel === f.properties.id;
  f.properties.dim = !!sel && sel !== f.properties.id;
  return f;
});

/**
 * Outline features of `active` groups: owner[i] = index in `active` of settlement i (or -1); `outlines` are city
 * outlines added to a group ({o: group index, key: city id, coords}). The centre of group a is its own settlement
 * or the outline with key === a.id.
 */
function hullFeatures(active, owner, outlines) {
  if (typeof Delaunator === 'undefined') return [];
  const S = agg.settlements;
  const groups = active.map(() => ({ lon: [], lat: [], city: [] }));  // city: key of the outline a point is on, else null
  for (let i = 0; i < owner.length; i++) {
    const g = groups[owner[i]];
    if (g) { g.lon.push(S.lon[i]); g.lat.push(S.lat[i]); g.city.push(null); }
  }
  for (const { o, key, coords } of outlines) {
    const g = groups[o];
    if (!g || !coords) continue;
    for (const [x, y] of coords) { g.lon.push(x); g.lat.push(y); g.city.push(key); }
  }
  const feats = [];
  active.forEach((a, o) => {
    const g = groups[o];
    const n = g.lon.length;
    if (n < 3) return;
    const xy = new Float64Array(2 * n);
    for (let i = 0; i < n; i++) { xy[2 * i] = g.lon[i] * HULL_KX; xy[2 * i + 1] = g.lat[i] * HULL_KY; }
    let d;
    try { d = new Delaunator(xy); } catch { return; }
    const V = d.triangles, H = d.halfedges, nT = V.length / 3;
    if (!nT) return;
    const len = (u, v) => Math.hypot(xy[2 * u] - xy[2 * v], xy[2 * u + 1] - xy[2 * v + 1]);
    const keep = new Uint8Array(nT);
    for (let t = 0; t < nT; t++) {
      const [p, q, r] = [V[3 * t], V[3 * t + 1], V[3 * t + 2]];
      const sameCity = g.city[p] != null && g.city[p] === g.city[q] && g.city[p] === g.city[r];
      keep[t] = sameCity || Math.max(len(p, q), len(q, r), len(r, p)) <= HULL_MAX_EDGE_KM ? 1 : 0;
    }
    // the connected part touching the centre (its outline or its own settlement)
    const isCentre = (v) => g.city[v] === a.id || (g.city[v] == null && g.lon[v] === S.lon[a.settlement] && g.lat[v] === S.lat[a.settlement]);
    const comp = new Int32Array(nT).fill(-1);
    let best = null;
    for (let t0 = 0; t0 < nT; t0++) {
      if (!keep[t0] || comp[t0] >= 0) continue;
      const tris = [t0];
      comp[t0] = t0;
      let centre = false;
      for (let k = 0; k < tris.length; k++) {
        const t = tris[k];
        for (let j = 0; j < 3; j++) {
          if (isCentre(V[3 * t + j])) centre = true;
          const h = H[3 * t + j];
          if (h < 0) continue;
          const u = Math.floor(h / 3);
          if (keep[u] && comp[u] < 0) { comp[u] = t0; tris.push(u); }
        }
      }
      const score = (centre ? 1e9 : 0) + tris.length;
      if (!best || score > best.score) best = { id: t0, tris, score };
    }
    if (!best) return;
    // boundary sides of that part, oriented as in their triangles
    const out = new Map();
    for (const t of best.tris) {
      for (let j = 0; j < 3; j++) {
        const e = 3 * t + j, h = H[e];
        if (h >= 0 && comp[Math.floor(h / 3)] === best.id) continue;
        const from = V[e], to = V[3 * t + ((j + 1) % 3)];
        if (!out.has(from)) out.set(from, []);
        out.get(from).push(to);
      }
    }
    // triangle orientation: interior on the left of every side when positive
    const t0 = best.tris[0];
    const [p0, p1, p2] = [V[3 * t0], V[3 * t0 + 1], V[3 * t0 + 2]];
    const sgn = Math.sign((xy[2 * p1] - xy[2 * p0]) * (xy[2 * p2 + 1] - xy[2 * p0 + 1]) - (xy[2 * p2] - xy[2 * p0]) * (xy[2 * p1 + 1] - xy[2 * p0 + 1]));
    const ang = (u, v) => Math.atan2(xy[2 * v + 1] - xy[2 * u + 1], xy[2 * v] - xy[2 * u]);
    const TAU = 2 * Math.PI;
    // at a vertex shared by several boundary sides, continue along the side bounding the same piece of area
    const nextOf = (prev, cur) => {
      const outs = out.get(cur);
      if (!outs?.length) return -1;
      const base = ang(cur, prev);
      let bi = 0, bd = Infinity;
      outs.forEach((w, i) => {
        let dd = sgn > 0 ? ang(cur, w) - base : base - ang(cur, w);
        dd = ((dd % TAU) + TAU) % TAU || TAU;
        if (dd < bd) { bd = dd; bi = i; }
      });
      return outs.splice(bi, 1)[0];
    };
    const lines = [];
    for (const [a0, outs] of out) {
      while (outs.length) {
        const ring = [a0];
        let prev = a0, cur = outs.pop();
        while (cur !== a0 && cur >= 0 && ring.length <= 2 * n) {
          ring.push(cur);
          const nx = nextOf(prev, cur);
          prev = cur; cur = nx;
        }
        if (cur !== a0 || ring.length < 3) continue;
        // outer rings run the same way as the triangles; holes the other way
        let area = 0;
        for (let i = 0; i < ring.length; i++) {
          const u = ring[i], v = ring[(i + 1) % ring.length];
          area += xy[2 * u] * xy[2 * v + 1] - xy[2 * v] * xy[2 * u + 1];
        }
        if (Math.sign(area) === sgn) lines.push([...ring, a0].map((v) => [g.lon[v], g.lat[v]]));
      }
    }
    if (lines.length) {
      feats.push({
        type: 'Feature', geometry: { type: 'MultiLineString', coordinates: lines },
        properties: { id: a.id, color: a.color },
      });
    }
  });
  return feats;
}

// ------------------------------------------------------------------ hromada budgets (OpenBudget)
/**
 * web/data/budgets.json: per city, the budget of its hromada (Kyiv: the city) by year, actual figures in UAH:
 * inc_* revenue groups, exp_* spending by function. Optional: the app works without it.
 */
let budgets = null;
async function loadBudgets() {
  if (budgets !== null) return budgets;
  try { budgets = await getJSON(`${DATA}/budgets.json`); } catch { budgets = { years: [], cities: {} }; }
  if (!budgets.years.includes(state.budgetYear)) state.budgetYear = budgets.years[0] ?? null;
  return budgets;
}
const otherOwn = (b) => b.inc_own - b.inc_pit - b.inc_single_tax - b.inc_property;
const BUDGET_INC = [
  { id: 'pit', key: 'budget.inc.pit', color: '#2f6db5', v: (b) => b.inc_pit },
  { id: 'single', key: 'budget.inc.single', color: '#5b9bd5', v: (b) => b.inc_single_tax },
  { id: 'property', key: 'budget.inc.property', color: '#8cc1e6', v: (b) => b.inc_property },
  { id: 'own', key: 'budget.inc.otherOwn', color: '#bcd8ee', v: otherOwn },
  { id: 'transfers', key: 'budget.inc.transfers', color: '#e08a1e', v: (b) => b.inc_transfers },
  { id: 'other', key: 'budget.inc.other', color: '#c4c9cf', v: (b) => b.inc_total - b.inc_own - b.inc_transfers },
];
const EXP_MAIN = ['exp_education', 'exp_health', 'exp_social', 'exp_housing', 'exp_economy', 'exp_culture', 'exp_admin', 'exp_transfers'];
const BUDGET_EXP = [
  { id: 'education', key: 'budget.exp.education', color: '#2e9d6a', v: (b) => b.exp_education },
  { id: 'health', key: 'budget.exp.health', color: '#d1495b', v: (b) => b.exp_health },
  { id: 'social', key: 'budget.exp.social', color: '#7b52ae', v: (b) => b.exp_social },
  { id: 'housing', key: 'budget.exp.housing', color: '#e08a1e', v: (b) => b.exp_housing },
  { id: 'economy', key: 'budget.exp.economy', color: '#6c8a1f', v: (b) => b.exp_economy },
  { id: 'culture', key: 'budget.exp.culture', color: '#1c9aa8', v: (b) => b.exp_culture },
  { id: 'admin', key: 'budget.exp.admin', color: '#8c6d3f', v: (b) => b.exp_admin },
  { id: 'transfers', key: 'budget.exp.transfers', color: '#9aa3ad', v: (b) => b.exp_transfers },
  { id: 'other', key: 'budget.exp.other', color: '#c4c9cf', v: (b) => b.exp_total - EXP_MAIN.reduce((a, k) => a + b[k], 0) },
];
const budgetGroups = (kind) => (kind === 'inc' ? BUDGET_INC : BUDGET_EXP);
const budgetTotal = (b, kind) => (kind === 'inc' ? b.inc_total : b.exp_total);

/** {e: city entry, b: figures of the year | null, occupied} or null when the city has no hromada budget. */
function budgetOf(cityId, year = state.budgetYear) {
  const e = budgets?.cities?.[cityId];
  if (!e) return null;
  const y = e.years[year];
  return { e, b: y && !y.occupied ? y : null, occupied: !!y?.occupied };
}
/** Money: 21,6 млрд грн / 345 млн грн / 12 345 грн. */
function fmtMoney(v) {
  const a = Math.abs(v);
  if (a >= 1e9) return `${num(v / 1e9, a >= 1e11 ? 0 : 1)} ${t('budget.bn')}`;
  if (a >= 1e6) return `${num(v / 1e6, a >= 1e8 ? 0 : 1)} ${t('budget.mn')}`;
  return `${fmtInt(v)} ${t('budget.uah')}`;
}
const perResident = (v, e) => v / Math.max(e.population, 1);
function budgetYearControl(onChange = renderAll) {
  const years = budgets?.years || [];
  if (years.length < 2) return el('span', { class: 'small' }, String(state.budgetYear ?? ''));
  const sel = el('select', { class: 'year-select', 'aria-label': t('budget.year') }, years.map((y) => el('option', { value: y }, String(y))));
  sel.value = state.budgetYear;
  sel.addEventListener('change', () => {
    state.budgetYear = +sel.value;
    try { localStorage.setItem('budgetYear', String(state.budgetYear)); } catch { /* storage unavailable */ }
    writeHash();
    onChange();
  });
  return sel;
}
function budgetPopNote(e) {
  return t(state.budgetYear > 2022 ? 'budget.popNote2025' : 'budget.popNote', { pop: fmtInt(e.population) });
}

/**
 * Map sidebar: the hromada budget — revenue and spending (total or per resident, both shown), each expandable into
 * its items, like the territory legend; notes go to the bottom of the sidebar.
 */
function renderBudgetPanel(list, names) {
  const box = $('#budgetPanel');
  box.innerHTML = '';
  if (!budgets?.years?.length) { setNotes('#notesBudget', []); return; }
  const dual = list.length > 1;
  const pc = state.budgetUnit === 'pc';
  const data = list.map((x) => budgetOf(x.city.id));
  const unit = el('div', { class: 'unit-toggle' }, [['total', t('budget.unit.total')], ['pc', t('budget.unit.pc')]].map(([id, text]) =>
    el('button', { class: (state.budgetUnit || 'total') === id ? 'active' : '', onclick: () => { state.budgetUnit = id; renderSidebar(); } }, text)));
  const head = el('div', { class: 'side-head' }, el('h3', {}, t('budget.title')), budgetYearControl(), unit);
  const ok = data.map((d) => d?.b || null);
  const metric = (v, i) => (pc ? perResident(v, data[i].e) : v);
  const main = (v) => (pc ? `${fmtInt(v)} ${t('budget.uah')}` : fmtMoney(v));
  const other = (v, i) => (pc ? fmtMoney(v * data[i].e.population) : `${fmtInt(perResident(v, data[i].e))} ${t('budget.perResidentShort')}`);
  const sides = [['inc', 'budget.income', '#2f6db5'], ['exp', 'budget.expenses', '#d1495b']];
  const topMax = Math.max(...sides.flatMap(([k]) => ok.map((b, i) => (b ? metric(budgetTotal(b, k), i) : 0))), 1);
  const rows = sides.map(([kind, key, color]) => {
    const open = state.budgetOpen.has(kind);
    const groups = budgetGroups(kind);
    const subMax = Math.max(...groups.flatMap((g) => ok.map((b, i) => (b ? metric(Math.max(g.v(b), 0), i) : 0))), 1);
    return {
      color, name: t(key), total: true, open,
      onToggle: () => { open ? state.budgetOpen.delete(kind) : state.budgetOpen.add(kind); renderSidebar(); },
      values: ok.map((b, i) => (b ? metric(budgetTotal(b, kind), i) : null)), max: topMax,
      text: (v) => main(v), sec: (v, i) => other(v, i),
      tip: () => `<b>${t(key)}</b>` + ok.map((b, i) => (b ? `<br>${dual ? names[i] + ': ' : ''}${fmtMoney(budgetTotal(b, kind))} · ${fmtInt(perResident(budgetTotal(b, kind), data[i].e))} ${t('budget.perResidentShort')}` : '')).join(''),
      children: groups.filter((g) => ok.some((b) => b && g.v(b) > 0)).map((g) => ({
        color: g.color, name: t(g.key), max: subMax,
        values: ok.map((b, i) => (b ? metric(Math.max(g.v(b), 0), i) : null)),
        text: (v) => main(v), sec: (v, i) => `${num((100 * g.v(ok[i])) / Math.max(budgetTotal(ok[i], kind), 1), 1)}%`,
        tip: () => `<b>${t(g.key)}</b>` + ok.map((b, i) => (b ? `<br>${dual ? names[i] + ': ' : ''}${fmtMoney(g.v(b))} · ${fmtInt(perResident(g.v(b), data[i].e))} ${t('budget.perResidentShort')} · ${num((100 * g.v(b)) / Math.max(budgetTotal(b, kind), 1), 1)}%` : '')).join(''),
      })),
    };
  });
  const why = (d) => (!d ? t('budget.noData') : d.occupied ? t('budget.occupied') : null);
  box.append(el('div', { class: 'panel demo' }, head,
    ok.some(Boolean) ? sideRows(rows, dual, names) : el('div', { class: 'small demo-note' }, why(data[0]))));
  const whose = (d) => (d.e.katottg === 'UA80000000000093317' ? t('budget.ofKyiv') : t('budget.ofHromada', { name: d.e.name }));
  setNotes('#notesBudget', [
    ...data.map((d, i) => {
      const n = d?.b ? whose(d) : why(d);
      return dual ? `${names[i]}: ${n}` : n;
    }),
    ok.some(Boolean) ? (dual ? t(state.budgetYear > 2022 ? 'budget.popNote2025' : 'budget.popNote', { pop: '' }).replace(' ()', '')
      : budgetPopNote(data[0].e)) : null,
    t('budget.source', { year: state.budgetYear }),
  ]);
}

/** Budgets & population screen: year switches of both data sets (population; budget). */
function financeYearControls() {
  const box = el('div', { class: 'year-controls' });
  if (demoYears().length) box.append(el('span', { class: 'demo-year' }, `${t('cmp.popYear')}: `, demoYearControl()));
  if (budgets?.years?.length) box.append(el('span', { class: 'demo-year' }, `${t('cmp.budgetYear')}: `, budgetYearControl(renderCompare)));
  return box;
}

/**
 * Budgets & population screen, budget revenue or spending: one stacked bar per city by item, total or per resident.
 * A click on an item (legend or bar) compares that item alone, cities sorted by it.
 */
function renderBudgetCompare(all, kind) {
  const pc = state.budgetMetric !== 'total';
  const groups = budgetGroups(kind);
  if (state.budgetFocus && !groups.some((g) => g.id === state.budgetFocus)) state.budgetFocus = null;
  const focus = groups.find((g) => g.id === state.budgetFocus) || null;
  const setFocus = (id) => { hideTip(); state.budgetFocus = state.budgetFocus === id ? null : id; writeHash(); renderCompare(); };
  const box = $('#unitToggleCompare');
  box.innerHTML = '';
  for (const [id, text] of [['pc', t('budget.metric.pc')], ['total', t('budget.metric.total')]]) {
    box.append(el('button', { class: (state.budgetMetric || 'pc') === id ? 'active' : '', onclick: () => { state.budgetMetric = id; renderCompare(); } }, text));
  }
  const fbar = $('#compareFocus');
  fbar.innerHTML = '';
  fbar.append(financeYearControls());
  if (focus) {
    fbar.append(el('span', { class: 'focus-chip', style: `--c:${focus.color}` }, el('i'), t('cmp.budgetFocus', { item: t(focus.key) }),
      el('button', { type: 'button', title: t('cmp.focusClear'), 'aria-label': t('cmp.focusClear'), onclick: () => setFocus(focus.id) }, '✕')));
  }
  $('#compareHint').textContent = focus ? t('cmp.hint.budgetFocus', { item: t(focus.key) }) : `${t('cmp.hint.budget')} ${t('cmp.hint.budgetClick')}`;
  const chart = $('#compareChart');
  chart.innerHTML = '';
  if (!all.length) {
    chart.append(el('p', { class: 'hint' }, t('cmp.noCities')));
    $('#compareLegend').innerHTML = '';
    $('#compareTable').innerHTML = '';
    return;
  }
  const rows = all.map((s) => ({ s, d: budgetOf(s.city.id) }));
  const scale = (r) => (pc ? 1 / Math.max(r.d.e.population, 1) : 1);
  const amount = (r) => (focus ? Math.max(focus.v(r.d.b), 0) : budgetTotal(r.d.b, kind));
  const value = (r) => (r.d?.b ? amount(r) * scale(r) : -1);
  rows.sort((a, b) => value(b) - value(a));
  const max = Math.max(...rows.map(value), 1);
  const show = (v) => (pc ? `${fmtInt(v)} ${t('budget.perResidentShort')}` : fmtMoney(v));
  for (const r of rows) {
    const { s, d } = r;
    const stack = el('div', { class: 'stack' + (focus ? ' focused' : '') });
    if (d?.b) {
      const total = budgetTotal(d.b, kind);
      stack.style.width = `${(100 * value(r)) / max}%`;
      for (const g of focus ? [focus] : groups) {
        const v = g.v(d.b);
        if (v <= 0) continue;
        const share = (100 * v) / Math.max(total, 1);
        const w = focus ? 100 : share;
        const seg = el('div', { class: 'seg' + (focus ? ' active' : ''), style: `width:${w}%;background:${g.color}`, role: 'button', tabindex: '0' },
          el('span', { style: isLight(g.color) ? 'color:#333;text-shadow:none' : '' }, focus ? (w > 0 ? `${num(share, 1)}%` : '') : (w > 9 ? `${num(w, 0)}%` : '')));
        seg.addEventListener('mousemove', (ev) => showTip(ev, `<b>${cityName(s.city)} — ${t(g.key)}</b><br>${fmtMoney(v)} · ${num(share, 1)}%`
          + `<br>${fmtInt(perResident(v, d.e))} ${t('budget.perResidentShort')}`));
        seg.addEventListener('mouseleave', hideTip);
        seg.addEventListener('click', () => setFocus(g.id));
        seg.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setFocus(g.id); } });
        stack.append(seg);
      }
    }
    const note = !d ? t('budget.noData') : d.occupied ? t('budget.occupied')
      : d.e.katottg === 'UA80000000000093317' ? t('budget.ofKyiv') : t('budget.ofHromada', { name: d.e.name });
    chart.append(el('div', { class: 'chart-row' },
      el('button', {
        type: 'button', class: 'city link', title: t('cmp.openMap', { city: cityName(s.city) }),
        onclick: () => { state.city = s.city.id; if (state.city2 === s.city.id) state.city2 = null; switchView('map'); },
      }, cityName(s.city), el('span', { class: 'terr-mark', title: note }, ' ⓘ')),
      el('div', {}, stack),
      el('div', { class: 'total' }, d?.b ? (focus
        ? el('span', { class: 'focus-value' }, show(value(r)), el('span', { class: 'small' }, ` · ${pc ? fmtMoney(amount(r)) : `${fmtInt(perResident(amount(r), d.e))} ${t('budget.perResidentShort')}`}`))
        : show(value(r))) : '—')));
  }
  const lg = $('#compareLegend');
  lg.innerHTML = '';
  for (const g of groups) {
    const on = state.budgetFocus === g.id;
    lg.append(el('button', {
      type: 'button', class: 'legend-item' + (on ? ' active' : '') + (focus && !on ? ' dim' : ''), 'aria-pressed': on, onclick: () => setFocus(g.id),
    }, el('i', { style: `background:${g.color}` }), t(g.key)));
  }
  $('#compareNote').textContent = `${t('budget.source', { year: state.budgetYear })} ${t(state.budgetYear > 2022 ? 'budget.popNote2025' : 'budget.popNote', { pop: '' }).replace(' ()', '')}`;
  const details = $('#compareTableDetails');
  if (!details.dataset.bound) {
    details.addEventListener('toggle', () => { if (details.open) renderCompareTable(); });
    details.dataset.bound = '1';
  }
  if (details.open) renderCompareTable(all);
  else $('#compareTable').innerHTML = '';
}

function renderBudgetTable(all, kind) {
  const groups = budgetGroups(kind);
  const head = el('tr', {}, el('th', {}, t('cmp.city')), el('th', {}, t('budget.total')), el('th', {}, t('budget.perResidentShort')),
    groups.map((g) => el('th', {}, `${t(g.key)}, ${t('budget.perResidentShort')}`)));
  const body = all.map((s) => {
    const d = budgetOf(s.city.id);
    if (!d?.b) return el('tr', {}, el('td', {}, cityName(s.city)), el('td', { colspan: groups.length + 2 }, d?.occupied ? t('budget.occupied') : t('budget.noData')));
    const total = budgetTotal(d.b, kind);
    return el('tr', {}, el('td', {}, cityName(s.city)), el('td', {}, fmtMoney(total)), el('td', {}, fmtInt(perResident(total, d.e))),
      groups.map((g) => el('td', {}, fmtInt(perResident(g.v(d.b), d.e)))));
  });
  $('#compareTable').innerHTML = '';
  $('#compareTable').append(el('table', {}, el('thead', {}, head), el('tbody', {}, body)));
}

// ------------------------------------------------------------------ region modelling
const modelView = { map: null, ready: null, result: null, frame: null };
const validThreshold = (m) => Number.isInteger(m) && m >= 0 && m <= agg.max_min && m % POP_STEP === 0;
const regionCentreIds = () => {
  const known = new Set(agg.centres.map((c) => c.id));
  if (state.regionCentres?.[0] === 'all') return agg.centres.filter((c) => c.settlement != null).map((c) => c.id);  // rc=all
  return (state.regionCentres || state.index.default_region_centres || []).filter((id) => known.has(id));
};

/**
 * Regions: every settlement joins the chosen centre it is reached from fastest (within the computed maximum);
 * no centre absorbs another. The core of a region is what lies within T minutes of its centre.
 */
function computeRegions(T, year, ids) {
  const S = agg.settlements;
  const pop = S.pop[year] || [];
  const lim = T * 10;
  const byId = Object.fromEntries(agg.centres.map((c) => [c.id, c]));
  const active = ids.map((id) => byId[id]).filter((c) => c && c.settlement != null).map((c, idx) => ({
    ...c, idx, city: cityById(c.id) || { id: c.id, name: c.name, name_local: c.name_local },
    cityPop: pop[c.settlement] ?? null, total: 0, core: 0, n: 0, nCore: 0,
  }));
  const owner = new Int16Array(S.code.length).fill(-1);
  const best = new Float32Array(S.code.length).fill(Infinity);
  for (const a of active) { owner[a.settlement] = a.idx; best[a.settlement] = -1; }  // a centre is its own
  for (const a of active) {
    for (const [i, tt] of aggReach[a.id] || []) if (tt < best[i]) { best[i] = tt; owner[i] = a.idx; }
  }
  const core = new Uint8Array(S.code.length);
  for (let i = 0; i < owner.length; i++) {
    const o = owner[i];
    if (o < 0) continue;
    const a = active[o], n = pop[i] || 0, inCore = best[i] <= lim;
    core[i] = inCore ? 1 : 0;
    a.total += n;
    a.n += 1;
    if (inCore) { a.core += n; a.nCore += 1; }
  }
  assignAggColors(active, owner, 1);  // neighbours by settlements of the whole region
  return { active, owner, core, pop, best };
}

function setModelThreshold(m, final = true) {
  state.modelThreshold = m;
  if (final) writeHash();
  if (modelView.frame) return;
  modelView.frame = requestAnimationFrame(async () => {
    try { await renderModelingView(); } finally { modelView.frame = null; }
  });
}

function setRegionCentres(ids) {
  const def = state.index.default_region_centres || [];
  const same = ids.length === def.length && ids.every((id) => def.includes(id));
  state.regionCentres = same ? null : ids;
  if (state.modelSelected && !ids.includes(state.modelSelected)) state.modelSelected = null;
  writeHash();
  renderModelingView();
}

function selectModelCentre(id) {
  state.modelSelected = state.modelSelected === id ? null : id;
  renderModelingView();
}

async function renderModelingView() {
  try { await loadAgglomeration(); } catch {
    $('#mChart').innerHTML = '';
    $('#mChart').append(el('p', { class: 'hint' }, t('pop.noFile')));
    return;
  }
  if (!validThreshold(state.modelThreshold)) state.modelThreshold = 60;
  const T = state.modelThreshold;
  const ids = regionCentreIds();
  const res = computeRegions(T, state.demoYear, ids);
  modelView.result = res;
  const max = fmtThreshold(agg.max_min);

  // controls
  const th = $('#mThreshold');
  th.innerHTML = '';
  for (const m of agg.thresholds_min) {
    th.append(el('button', {
      type: 'button', class: T === m ? 'active' : '', 'aria-pressed': T === m, onclick: () => setModelThreshold(m),
    }, fmtThreshold(m)));
  }
  const slider = $('#mSlider');
  slider.max = agg.max_min;
  slider.step = POP_STEP;
  if (document.activeElement !== slider) slider.value = T;
  slider.oninput = () => { $('#mSliderVal').textContent = fmtThreshold(+slider.value); setModelThreshold(+slider.value, false); };
  slider.onchange = () => setModelThreshold(+slider.value);
  $('#mSliderVal').textContent = fmtThreshold(T);
  const yb = $('#mYear');
  yb.innerHTML = '';
  yb.append(`${t('demo.title')}: `, demoYearControl());
  $('#mHint').textContent = T === 0 ? t('model.hint.city') : t('model.hint', { t: fmtThreshold(T), max });
  const legend = $('#mLegend');
  legend.innerHTML = '';
  legend.append(
    el('span', { class: 'pop-legend-item core' }, el('i'), el('i', { class: 'line' }), T === 0 ? t('model.coreCity') : t('model.core', { t: fmtThreshold(T) })),
    el('span', { class: 'pop-legend-item rest' }, el('i'), el('i', { class: 'line' }), t('model.rest')),
    el('span', { class: 'pop-legend-item outside' }, el('i'), t('model.none', { max })),
  );

  // centre picker: every city with drive times, by city group
  const chosen = new Set(ids);
  const colorOf = Object.fromEntries(res.active.map((a) => [a.id, a.color]));
  $('#mPickerSummary').textContent = t('model.centres', { n: ids.length, total: agg.centres.length });
  const acts = $('#mPickerActions');
  acts.innerHTML = '';
  acts.append(
    el('button', { type: 'button', onclick: () => setRegionCentres([...(state.index.default_region_centres || [])]) }, t('model.default')),
    el('button', { type: 'button', onclick: () => setRegionCentres(agg.centres.filter((c) => c.settlement != null).map((c) => c.id)) }, t('model.all')),
    el('button', { type: 'button', onclick: () => setRegionCentres([]) }, t('model.clear')),
  );
  const list = $('#mCentres');
  const scroll = list.scrollTop;
  list.innerHTML = '';
  const aggIds = new Set(agg.centres.map((c) => c.id));
  for (const g of cityGroups()) {
    const cities = state.index.cities.filter((c) => (c.group || '') === (g.id || '') && aggIds.has(c.id))
      .sort((a, b) => cityName(a).localeCompare(cityName(b), getLang()));
    if (!cities.length) continue;
    list.append(el('h4', {}, getLang() === 'uk' ? g.label_uk || g.label : g.label));
    for (const c of cities) {
      const box = el('input', { type: 'checkbox' });
      box.checked = chosen.has(c.id);
      box.addEventListener('change', () => setRegionCentres(box.checked ? [...ids, c.id] : ids.filter((x) => x !== c.id)));
      list.append(el('label', {}, box, el('i', { style: `background:${colorOf[c.id] || 'transparent'}` }), cityName(c)));
    }
  }
  list.scrollTop = scroll;

  // bar chart: regions by population — the centre city, the rest of the core, the rest of the region
  const chart = $('#mChart');
  chart.innerHTML = '';
  if (!res.active.length) chart.append(el('p', { class: 'hint' }, t('model.empty')));
  const rows = [...res.active].sort((a, b) => b.total - a.total);
  const top = Math.max(...rows.map((c) => c.total), 1);
  const sel = state.modelSelected;
  for (const c of rows) {
    const city = c.cityPop || 0;
    const pct = (v) => (c.total ? (100 * v) / c.total : 0);
    const row = el('div', { class: 'pop-row' + (sel === c.id ? ' sel' : '') + (sel && sel !== c.id ? ' dim' : ''), 'data-id': c.id },
      el('div', { class: 'name', title: cityName(c.city) }, cityName(c.city)),
      el('div', {}, el('div', { class: 'bar', style: `width:${(100 * c.total) / top}%` },
        el('i', { style: `width:${pct(city)}%;background:${c.color}` }),
        el('i', { style: `width:${pct(c.core - city)}%;background:${c.color};opacity:.6` }),
        el('i', { style: `width:${pct(c.total - c.core)}%;background:${c.color};opacity:.22` }))),
      el('div', { class: 'val' }, fmtInt(c.total)));
    row.addEventListener('mousemove', (ev) => showTip(ev, regionTip(c)));
    row.addEventListener('mouseleave', hideTip);
    row.addEventListener('click', () => selectModelCentre(c.id));
    chart.append(row);
  }
  $('#mNote').textContent = t('model.note') + ' ' + demoSource() + '.';
  await ensureModelMap();
  updateModelMap();
}

/** Tooltip of a region: total, core, rest, centre city. */
function regionTip(c) {
  const T = state.modelThreshold;
  return `<b>${cityName(c.city)}</b><br>${t('model.region')}: ${fmtInt(c.total)} (${t('pop.nSett', { n: fmtInt(c.n) })})`
    + `<br>${T ? t('model.inCore', { t: fmtThreshold(T) }) : t('model.coreCity')}: ${fmtInt(c.core)}`
    + `<br>${t('model.inRest')}: ${fmtInt(c.total - c.core)}`
    + `<br>${t('demo.cityOnly')}: ${c.cityPop == null ? t('pop.noPop') : fmtInt(c.cityPop)}`;
}

async function ensureModelMap() {
  if (modelView.map) { modelView.map.resize(); return modelView.ready; }
  Object.assign(modelView, createAggMap('modelMap', {
    centreTip: (p) => `${regionTip(modelView.result.active.find((a) => a.id === p.id))}<br><i>${t('model.clickRemove')}</i>`,
    settTip: (f) => `${settTipHead(f)} · ${f.in ? `${num(f.t, 0)} ${t('set.min')} → ${f.centre}${f.pale ? ` (${t('model.beyond')})` : ''}` : t('model.outside')}`
      + (f.city ? `<br><i>${t('model.clickAdd')}</i>` : ''),
    // a click on the map toggles a city's centre status (the chart rows highlight a region)
    onCentreClick: (id) => { hideTip(); setRegionCentres(regionCentreIds().filter((x) => x !== id)); },
    onSettClick: (f) => { hideTip(); setRegionCentres([...regionCentreIds(), f.city]); },
  }));
  return modelView.ready;
}

function updateModelMap() {
  const map = modelView.map;
  if (!map || !map.getSource('centres')) return;
  const { active, owner, core, pop, best } = modelView.result;
  const S = agg.settlements;
  const sel = state.modelSelected;
  const cityAt = Object.fromEntries(agg.centres.filter((c) => c.settlement != null).map((c) => [c.settlement, c.id]));  // can become centres
  // circle areas relative to the largest region; with no region, to the largest settlement (not to 1 person)
  const maxTotal = active.length ? Math.max(...active.map((c) => c.total), 1)
    : pop.reduce((m, n) => Math.max(m, n || 0), 1);
  const centres = active.map((c) => ({
    type: 'Feature', geometry: { type: 'Point', coordinates: [S.lon[c.settlement], S.lat[c.settlement]] },
    properties: { id: c.id, color: c.color, r: 34 * Math.sqrt(c.total / maxTotal), sel: sel === c.id, dim: !!sel && sel !== c.id, total: c.total },
  })).sort((a, b) => b.properties.total - a.properties.total);  // small circles on top
  const sett = [];
  for (let i = 0; i < owner.length; i++) {
    const o = owner[i];
    const c = o >= 0 ? active[o] : null;
    if (c?.settlement === i) continue;  // the centre's own circle
    const n = pop[i] || 0;
    sett.push({
      type: 'Feature', geometry: { type: 'Point', coordinates: [S.lon[i], S.lat[i]] },
      properties: {
        i, pop: n, cls: popClass(n), r: 34 * Math.sqrt(n / maxTotal), in: !!c, pale: !!c && !core[i],
        color: c ? c.color : POP_OUTSIDE, t: c ? Math.max(0, best[i]) / 10 : null,
        centre: c ? cityName(c.city) : null, dim: !!sel && sel !== c?.id, city: cityAt[i] || '',
      },
    });
  }
  // outlines: the core (within T) and the whole region. Every city of the region counts with its whole area (its
  // outline), not only the centre: a city is a point among the settlements, and gaps of more than
  // HULL_MAX_EDGE_KM around it (Sevastopol and its villages) would cut it off
  const cityOutlines = agg.centres.filter((c) => c.settlement != null && owner[c.settlement] >= 0 && c.outline)
    .map((c) => ({ o: owner[c.settlement], key: c.id, coords: c.outline, core: !!core[c.settlement] }));
  const coreOwner = owner.map((o, i) => (core[i] ? o : -1));
  map.getSource('centres').setData({ type: 'FeatureCollection', features: centres });
  map.getSource('hull').setData({ type: 'FeatureCollection', features: withSel(hullFeatures(active, coreOwner, cityOutlines.filter((c) => c.core)), sel) });
  map.getSource('hull-outer').setData({ type: 'FeatureCollection', features: withSel(hullFeatures(active, owner, cityOutlines), sel) });
  map.getSource('sett').setData({ type: 'FeatureCollection', features: sett });
}

// ------------------------------------------------------------------ bundled PMTiles
let pmProtocol = null;
const bundleSources = new Map();  // bundle URL -> FetchSource (one per file, so ETags stay consistent)

/** A PMTiles archive stored at [offset, offset + length) of a larger file, read with HTTP range requests. */
class SliceSource {
  constructor(fetchSource, offset, length, key) { Object.assign(this, { fetchSource, offset, length, key }); }
  getKey() { return this.key; }
  getBytes(offset, length, signal, etag) {
    // never read past the slice (the header read asks for 16 KB, more than a small archive)
    const n = Math.max(1, Math.min(length, this.length - offset));
    return this.fetchSource.getBytes(this.offset + offset, n, signal, etag);
  }
}

/** Register the archive at `[offset, length]` of `url` with the pmtiles protocol; returns its protocol key. */
function bundleSlice(url, [offset, length]) {
  const key = `${url}@${offset}`;
  if (!pmProtocol.get(key)) {
    if (!bundleSources.has(url)) bundleSources.set(url, new pmtiles.FetchSource(url));
    pmProtocol.add(new pmtiles.PMTiles(new SliceSource(bundleSources.get(url), offset, length, key)));
  }
  return key;
}

// ------------------------------------------------------------------ views
/** Two-level menu: top-level sections and the screens (views) in each. */
const SECTIONS = { cities: ['map', 'compare', 'finance'], regions: ['population', 'modeling'], about: ['about'] };
const VIEW_SECTION = { finance: 'compare' };  // views drawn into another view's section
const sectionEl = (view) => `view-${VIEW_SECTION[view] || view}`;
const sectionOf = (view) => Object.keys(SECTIONS).find((s) => SECTIONS[s].includes(view)) || 'cities';
const lastView = {};  // section -> screen last open in it

function switchView(view) {
  if (!document.getElementById(sectionEl(view))) view = 'map';
  state.view = view;
  const section = sectionOf(view);
  lastView[section] = view;
  document.querySelectorAll('.tab').forEach((b) => b.classList.toggle('active', b.dataset.section === section));
  document.querySelectorAll('.subtab-group').forEach((g) => { g.hidden = g.dataset.section !== section; });
  $('#subtabs').hidden = SECTIONS[section].length < 2;
  document.querySelectorAll('.subtab').forEach((b) => b.classList.toggle('active', b.dataset.view === view));
  document.querySelectorAll('.view').forEach((v) => v.classList.toggle('active', v.id === sectionEl(view)));
  if (view === 'map') {
    for (const p of activePanes()) p.map.resize();
    selectCities(state.city, state.city2, false);
  }
  if (view === 'compare' || view === 'finance') renderCompare();
  if (view === 'about') renderAbout();
  if (view === 'population') renderPopulationView();
  if (view === 'modeling') renderModelingView();
  hideTip();
  writeHash();
}

/** Set main / second city of the map screen; reloads (and refits) panes when the cities changed. */
async function selectCities(city, city2, fit = true) {
  if (city2 && !state.city2) state.territory2 = state.territory; // entering split screen
  // comparing a city with itself only makes sense in different territories
  if (city2 && city2 === city && state.territory2 === state.territory) {
    state.territory2 = state.territory === 'city' ? 'greater' : 'city';
  }
  const changed = city !== panes[0].cityId || (city2 || null) !== (panes[1]?.cityId || null);
  state.city = city;
  state.city2 = city2 || null;
  fillCitySelects();
  await Promise.all([loadStats(city), city2 ? loadStats(city2) : null]);
  if (state.unit === 'pctcat') state.unit = 'pct';
  renderTerritoryToggles();
  renderSidebar();
  writeHash(); // before waiting for the map, so the URL is right even while tiles load
  if (changed) await updateMaps({ fit });
  else if (panes[1]?.map && panes[1].mode !== paneStats(1)?._mode) { // same cities, pane 1 territory changed
    await loadCityIntoPane(panes[1], state.city2);
    renderPaneLabels();
    fitPanes();
  }
}

function renderAll() {
  if (state.view === 'map') renderSidebar();
  if (state.view === 'compare' || state.view === 'finance') renderCompare();
  if (state.view === 'population') renderPopulationView();
  if (state.view === 'modeling') renderModelingView();
}

// ------------------------------------------------------------------ territory modes
function renderTerritoryToggles() {
  const toggle = (cur, idx) => el('div', { class: 'unit-toggle terr-toggle', role: 'group' }, TERRITORIES.map((m) => el('button', {
    type: 'button', class: cur === m ? 'active' : '', 'aria-pressed': cur === m,
    title: t(`terr.${m}.hint`), onclick: () => setTerritory(m, idx),
  }, t(`terr.${m}`))));
  const cmp = $('#territoryCompare');
  if (cmp) {
    cmp.innerHTML = '';
    cmp.append(el('span', { class: 'terr-label' }, t('terr.label')), toggle(state.territory, 0));
  }
  const box = $('#territoryMap');
  if (!box) return;
  box.innerHTML = '';
  box.append(el('span', { class: 'terr-label' }, t('terr.label')));
  if (!isDual()) {
    box.append(toggle(state.territory, 0));
    return;
  }
  // split screen: one switch per pane, so a city can be compared with itself (e.g. city vs. Greater City)
  [state.city, state.city2].forEach((id, i) => box.append(el('div', { class: 'terr-pane' },
    el('span', { class: `city-key k${i}`, title: cityName(cityById(id)) }), toggle(paneMode(i), i))));
}

async function setTerritory(mode, idx = 0) {
  if (!TERRITORIES.includes(mode) || mode === paneMode(idx)) return;
  if (idx === 1) {
    state.territory2 = mode;
    renderTerritoryToggles();
    hideTip();
    renderSidebar();
    if (panes[1]?.popup) panes[1].popup.remove();
    if (panes[1]?.cityId) await loadCityIntoPane(panes[1], panes[1].cityId);
    renderPaneLabels();
    fitPanes();
    writeHash();
    return;
  }
  state.territory = mode;
  try { localStorage.setItem('territory', mode); } catch { /* storage unavailable */ }
  renderTerritoryToggles();
  hideTip();
  if (state.view === 'compare' || state.view === 'finance') renderCompare();
  renderSidebar();
  renderPaneLabels();
  for (const p of activePanes()) if (p.popup) p.popup.remove();
  if (panes[0]?.cityId) await loadCityIntoPane(panes[0], panes[0].cityId);
  renderPaneLabels();
  fitPanes();
  writeHash();
}

/** Map sidebar: population of the shown territory (one column per pane in split screen). */
/**
 * A block of rows like the territory legend: swatch, name with one bar per city, one value column per city.
 * rows: [{color, name, values: [v per city], max, text: (v, i) => node|string, sec?: (v, i) => string,
 *         total?, open?, onToggle?, tip?: () => html}]
 */
function sideRows(rows, dual, heads) {
  const box = el('div', { class: 'side-rows' + (dual ? ' dual' : '') });
  if (dual) {
    box.append(el('div', { class: 'legend-row legend-head' }, el('span'), el('span'),
      ...heads.map((h, i) => el('div', { class: 'value' }, el('span', { class: `city-key k${i}` }), h))));
  }
  for (const r of rows) {
    const bars = el('div', { class: 'bars' }, r.values.map((v, i) => el('div', { class: 'bar' },
      el('span', { class: `k${i}`, style: `width:${v == null ? 0 : (100 * Math.max(v, 0)) / Math.max(r.max, 1e-9)}%;--c:${r.color}` }))));
    const row = el('div', { class: 'legend-row' + (r.total ? ' total' : '') },
      el('span', { class: 'swatch static', style: `background:${r.color}` }),
      el('div', { class: 'label' }, el('div', { class: 'name' },
        r.onToggle ? el('button', { class: 'expander', 'aria-expanded': !!r.open, onclick: r.onToggle }, r.open ? '▾' : '▸') : null, r.name), bars),
      ...r.values.map((v, i) => el('div', { class: 'value' }, v == null ? '—' : r.text(v, i),
        v != null && r.sec ? el('span', { class: 'sec' }, r.sec(v, i)) : null)));
    if (r.onToggle) row.querySelector('.name').addEventListener('click', (e) => { if (e.target.tagName !== 'BUTTON') r.onToggle(); });
    if (r.onToggle) row.querySelector('.name').style.cursor = 'pointer';
    if (r.tip) {
      row.addEventListener('mousemove', (ev) => showTip(ev, r.tip()));
      row.addEventListener('mouseleave', hideTip);
    }
    box.append(row);
    if (r.open && r.children?.length) {
      const sub = sideRows(r.children, dual, heads);
      box.append(el('div', { class: 'subrows side-rows' + (dual ? ' dual' : '') },
        [...sub.children].filter((c) => !c.classList.contains('legend-head'))));
    }
  }
  return box;
}

/** Notes of the side blocks, shown at the bottom of the sidebar. */
function setNotes(id, notes) {
  const box = $(id);
  box.innerHTML = '';
  for (const n of notes.filter(Boolean)) box.append(el('div', { class: 'small demo-note' }, n));
  $('#dataNotes').hidden = !$('#notesPop').childNodes.length && !$('#notesBudget').childNodes.length;
}

/** Map sidebar: population of the territory (total, city, rest) as rows with bars, like the territory legend. */
function renderPopulationPanel(list, names) {
  const box = $('#demographyPanel');
  box.innerHTML = '';
  if (!demoYears().length) { setNotes('#notesPop', []); return; }
  const dual = list.length > 1;
  const pops = list.map((x) => popOf(x));
  const head = el('div', { class: 'side-head' }, el('h3', {}, t('demo.title')), demoYearControl());
  const vals = (f) => pops.map((p) => (p ? f(p) : null));
  const max = Math.max(...pops.map((p) => p?.pop || 0), 1);
  const CITY = '#4a5a6a', REST = '#a9b4bf';
  const restMode = list.map((x) => x._mode).find((m) => m !== 'city');
  const rows = [{
    color: CITY, name: t('demo.population'), total: true, values: vals((p) => p.pop), max,
    text: (v) => fmtInt(v), sec: (v, i) => `${fmtInt(pops[i].density)} ${t('demo.densityShort')}`,
    tip: () => `<b>${t('demo.population')}</b>` + pops.map((p, i) => (p ? `<br>${dual ? names[i] + ': ' : ''}${fmtInt(p.pop)} ${t('demo.people')}, ${fmtInt(p.density)} ${t('demo.perKm2')}` : '')).join(''),
  }];
  if (restMode) {
    rows.push({ color: CITY, name: t('demo.cityOnly'), values: vals((p) => p.cityPop), max, text: (v) => fmtInt(v),
      sec: (v, i) => `${num((100 * v) / Math.max(pops[i].pop, 1), 0)}%` });
    rows.push({ color: REST, name: restLabel(restMode), values: list.map((x, i) => (pops[i] && x._mode !== 'city' ? pops[i].pop - pops[i].cityPop : (pops[i] ? 0 : null))),
      max, text: (v) => fmtInt(v), sec: (v, i) => `${num((100 * v) / Math.max(pops[i].pop, 1), 0)}%` });
  }
  box.append(el('div', { class: 'panel demo' }, head, sideRows(rows, dual, names)));
  // notes at the bottom of the sidebar
  setNotes('#notesPop', [
    ...list.map((x, i) => {
      const n = !pops[i] ? t('demo.noData') : demoEstimateNote(cityById(x.city.id));
      return n ? (dual ? `${names[i]}: ${n}` : n) : null;
    }),
    ...list.map((x, i) => (pops[i] && x._mode === 'greater' && pops[i].unmatched.length
      ? `${dual ? names[i] + ': ' : ''}${t('demo.unmatched', { n: pops[i].unmatched.length, names: pops[i].unmatched.map((n) => (n === '—' ? t('demo.unnamed') : n)).join(', ') })}` : null)),
    `${demoSource()}.`,
  ]);
}

const settlementsCache = {};
let settlementsToken = 0;
/** Greater City mode: list of included settlements with drive times (one block per city). */
async function renderSettlements(list, names = list.map((x) => cityName(x.city))) {
  const token = ++settlementsToken; // later renders supersede this one
  const box = $('#settlementsPanel');
  box.innerHTML = '';
  for (const [i, x] of list.entries()) {
    if (x._mode !== 'greater' || !x.map.settlements) continue;
    const id = x.city.id;
    if (!settlementsCache[id]) {
      try { settlementsCache[id] = await getJSON(`${DATA}/${id}/${x.map.settlements}`); } catch { continue; }
    }
    if (token !== settlementsToken) return; // superseded while loading
    const inc = settlementsCache[id].features.map((f) => f.properties).filter((p) => p.in_greater)
      .sort((a, b) => a.drive_min - b.drive_min);
    const d = rawStats[id].territories?.greater_drive_min ?? 10;
    box.append(el('details', { class: 'panel settlements' },
      el('summary', {}, el('h3', { style: 'display:inline' },
        t('set.title', { city: list.length > 1 ? names[i] + ': ' : '' }) + ` (${inc.length})`)),
      el('div', { class: 'small', style: 'margin:4px 0 6px' }, t('set.rule', { d: num(d, 0) })),
      el('ul', { class: 'set-list' }, inc.map((p) => {
        const pop = settlementPop(id, p.osm);
        return el('li', {},
          el('span', {}, p.name || '—', p.approx ? el('span', { class: 'small', title: t('set.approx') }, ' *') : null),
          el('span', { class: 'small' }, `${num(p.drive_min, 1)} ${t('set.min')}`
            + (pop != null ? ` · ${fmtInt(pop)} ${t('demo.peopleShort')}` : '')));
      })),
      inc.some((p) => p.approx) ? el('div', { class: 'small' }, `* ${t('set.approx')}`) : null));
  }
}

// ------------------------------------------------------------------ language
function fillCitySelects() {
  // grouped (<optgroup>) and sorted like every other city list
  const options = (skip) => citiesByGroup().flatMap(({ group, cities }) => {
    const opts = cities.filter((c) => c.id !== skip).map((c) => el('option', { value: c.id }, `${cityName(c)} (${cityOtherName(c)})`));
    if (!opts.length) return [];
    return label(group) ? [el('optgroup', { label: label(group) }, opts)] : opts;
  });
  const sel = $('#citySelect');
  sel.innerHTML = '';
  sel.append(...options(null));
  sel.value = state.city;
  const sel2 = $('#citySelect2');
  sel2.innerHTML = '';
  sel2.append(el('option', { value: '' }, t('city2.none')), ...options(null)); // the same city: compare territories
  sel2.value = state.city2 || '';
}

function changeLanguage(lang) {
  if (lang === getLang()) return;
  setLang(lang); // stores the cookie and refreshes static markup
  fillCitySelects();
  for (const p of activePanes()) {
    if (p.popup) p.popup.remove();
    addMapControls(p);
  }
  renderPaneLabels();
  renderTerritoryToggles();
  renderSidebar();
  if (state.view === 'compare' || state.view === 'finance') renderCompare();
  if (state.view === 'about') renderAbout();
  if (state.view === 'population') renderPopulationView();
  if (state.view === 'modeling') renderModelingView();
  hideTip();
}

// ------------------------------------------------------------------ boot
async function main() {
  applyStatic();
  document.querySelectorAll('.lang-switch button').forEach((b) => b.addEventListener('click', () => changeLanguage(b.dataset.lang)));
  try {
    state.index = await getJSON(`${DATA}/index.json`);
  } catch (e) {
    $('main').innerHTML = `<p style="padding:24px">${t('nodata', { cmd: '<code>python -m urbanfp run --all</code>' })} (${e.message})</p>`;
    return;
  }
  const defaultCity = state.index.cities[0].id; // first city in config/cities.yaml (Kyiv)
  state.index.cities = sortCities(state.index.cities);
  const h = readHash();
  const known = (id) => state.index.cities.some((c) => c.id === id);
  state.city = known(h.city) ? h.city : defaultCity;
  const city2 = known(h.city2) ? h.city2 : null;
  loadCompareCities(h.cities);
  let saved = null;
  try { saved = localStorage.getItem('territory'); } catch { /* storage unavailable */ }
  state.territory = TERRITORIES.includes(h.territory) ? h.territory : TERRITORIES.includes(saved) ? saved : 'city';
  if (city2 && TERRITORIES.includes(h.territory2)) {
    state.territory2 = h.territory2;
    state.city2 = city2; // keep t2 from the URL (selectCities resets it when entering split screen)
  }
  await loadDemography();
  let savedYear = null;
  try { savedYear = +localStorage.getItem('demoYear') || null; } catch { /* storage unavailable */ }
  for (const y of [h.year, savedYear]) if (y && demoYears().includes(y)) { state.demoYear = y; break; }
  await loadBudgets();
  let savedBudgetYear = null;
  try { savedBudgetYear = +localStorage.getItem('budgetYear') || null; } catch { /* storage unavailable */ }
  for (const y of [h.budgetYear, savedBudgetYear]) if (y && budgets.years.includes(y)) { state.budgetYear = y; break; }
  if (h.threshold != null && !Number.isNaN(h.threshold)) {
    if (h.view === 'modeling') state.modelThreshold = h.threshold; else state.popThreshold = h.threshold;
  }
  if (h.regionCentres) state.regionCentres = h.regionCentres;
  if (['population', 'budgetInc', 'budgetExp'].includes(h.financeBreakdown)) state.financeBreakdown = h.financeBreakdown;
  if (h.budgetFocus) state.budgetFocus = h.budgetFocus;
  renderTerritoryToggles();
  fillCitySelects();
  initCityFilter();
  $('#citySelect').addEventListener('change', (e) => selectCities(e.target.value, state.city2));
  $('#citySelect2').addEventListener('change', (e) => selectCities(state.city, e.target.value || null));
  document.querySelectorAll('.tab').forEach((b) => b.addEventListener('click',
    () => switchView(lastView[b.dataset.section] || SECTIONS[b.dataset.section][0])));
  document.querySelectorAll('.subtab').forEach((b) => b.addEventListener('click', () => switchView(b.dataset.view)));

  pmProtocol = new pmtiles.Protocol();
  maplibregl.addProtocol('pmtiles', pmProtocol.tile);
  createPane(0, 'map');
  window.app = { panes, state, popView, modelView }; // handy for debugging in the console

  $('#basemapToggle').addEventListener('change', (e) => {
    for (const p of activePanes()) p.map.setLayoutProperty('osm', 'visibility', e.target.checked ? 'visible' : 'none');
  });
  $('#boundaryToggle').addEventListener('change', (e) => {
    for (const p of activePanes()) {
      for (const id of ['boundary-line', 'territory-line']) {
        if (p.map.getLayer(id)) p.map.setLayoutProperty(id, 'visibility', e.target.checked ? 'visible' : 'none');
      }
    }
  });
  $('#opacityRange').addEventListener('input', (e) => { state.opacity = +e.target.value; applyOpacity(); });
  try { state.subPctOfCat = localStorage.getItem('subPctOfCat') !== 'false'; } catch { /* storage unavailable */ }
  $('#subPctCheckbox').addEventListener('change', (e) => {
    state.subPctOfCat = e.target.checked;
    try { localStorage.setItem('subPctOfCat', String(state.subPctOfCat)); } catch { /* storage unavailable */ }
    renderSidebar();
  });
  window.addEventListener('resize', () => { for (const p of activePanes()) p.map.resize(); });

  // open the requested view right away; the map keeps loading in the background
  const mapReady = selectCities(state.city, city2);
  if (h.aboutPage) state.aboutPage = h.aboutPage;
  if (h.view && h.view !== 'map') switchView(h.view);
  await mapReady;
}

main();
